#!/usr/bin/env node
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { validateOpenAPISpec } from "./openapi-spec.js";
import {
	loadArtifactProvenance,
	repositoryRoot,
} from "./repository-control-plane.mjs";

function assert(condition, message) {
	if (!condition) throw new Error(message);
}

function resolveOpenApiSpecPath(provenance, rootDir) {
	const sources = provenance?.sources;
	assert(Array.isArray(sources), "Artifact provenance sources are required");
	const matches = sources.filter((source) => source?.id === "openapi-spec");
	assert(
		matches.length === 1,
		"Artifact provenance must own exactly one OpenAPI source entry",
	);
	const [source] = matches;
	assert(
		Array.isArray(source.paths) && source.paths.length === 1,
		"Artifact provenance must own exactly one OpenAPI source path",
	);
	const [path] = source.paths;
	assert(
		typeof path === "string" && path.length > 0,
		"Artifact provenance OpenAPI source path must be non-empty",
	);
	return resolve(rootDir, path);
}

export async function checkOpenApiSpec(rootDir = repositoryRoot) {
	const provenance = loadArtifactProvenance(rootDir);
	const specPath = resolveOpenApiSpecPath(provenance, rootDir);
	const spec = JSON.parse(await readFile(specPath, "utf8"));
	validateOpenAPISpec(spec);
}

const isCli =
	process.argv[1] !== undefined &&
	import.meta.url === pathToFileURL(resolve(process.argv[1])).href;

if (isCli) {
	await checkOpenApiSpec();
	console.log("OpenAPI compatibility invariants are valid.");
}

import { access, readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { loadTopology, repositoryRoot } from "./repository-control-plane.mjs";

const root = repositoryRoot;
const topology = loadTopology(root);

const errors = [];
for (const workspace of topology.workspaces) {
	const { path: relative } = workspace;
	const allowed = workspace.exports.map((key) =>
		key === "." ? "." : `./${key.replace(/^\.\//, "")}`,
	);
	const path = resolve(root, relative, "package.json");
	let pkg;
	try {
		pkg = JSON.parse(await readFile(path, "utf8"));
	} catch (error) {
		errors.push(`${relative}: unable to read package.json (${error.message})`);
		continue;
	}
	if ((pkg.private !== true) !== workspace.publishable) {
		errors.push(`${relative}: package private/publishable metadata disagrees`);
	}
	if (allowed.length === 0) {
		if (pkg.exports !== undefined)
			errors.push(`${relative}: topology declares no public exports`);
		continue;
	}
	if (!pkg.exports || typeof pkg.exports !== "object") {
		errors.push(`${relative}: exports map is required`);
		continue;
	}
	const keys = Object.keys(pkg.exports);
	for (const key of keys) {
		if (!allowed.includes(key))
			errors.push(`${relative}: unexpected export ${key}`);
		if (key.includes("*"))
			errors.push(`${relative}: wildcard exports are forbidden`);
	}
	for (const key of allowed) {
		if (!(key in pkg.exports))
			errors.push(`${relative}: missing export ${key}`);
	}
	for (const [key, target] of Object.entries(pkg.exports)) {
		const record = typeof target === "string" ? { import: target } : target;
		if (!record || typeof record !== "object") {
			errors.push(`${relative}: export ${key} must be a condition map`);
			continue;
		}
		for (const [condition, value] of Object.entries(record)) {
			if (typeof value !== "string") {
				errors.push(`${relative}: export ${key}.${condition} must be a string`);
				continue;
			}
			if (value.includes("*") || value.includes("node_modules")) {
				errors.push(
					`${relative}: export ${key}.${condition} uses an unstable target`,
				);
			}
			if (workspace.publishable && !value.startsWith("./dist/")) {
				errors.push(
					`${relative}: public export ${key}.${condition} must target built dist files`,
				);
			}
			if (value.startsWith("./dist/") && !workspace.publishable) {
				try {
					await access(resolve(root, relative, value));
				} catch {
					// Built artifacts are optional for private source packages.
				}
			}
		}
	}
}

if (errors.length > 0) {
	console.error(errors.join("\n"));
	process.exitCode = 1;
} else {
	console.log("Package export maps are valid.");
}

import { existsSync } from "node:fs";
import { readdir, readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import {
	loadArtifactProvenance,
	loadTopology,
	repositoryRoot,
	workspaceById,
} from "./repository-control-plane.mjs";

function assert(condition, message) {
	if (!condition) throw new Error(message);
}

function uniqueProvenanceEntry(provenance, collection, id) {
	const entries = provenance?.[collection];
	assert(
		Array.isArray(entries),
		`Artifact provenance ${collection} entries are required`,
	);
	const matches = entries.filter((entry) => entry?.id === id);
	assert(
		matches.length === 1,
		`Artifact provenance ${collection} entry ${id} must be unique`,
	);
	const [entry] = matches;
	assert(
		Array.isArray(entry.paths) && entry.paths.length === 1,
		`Artifact provenance ${collection} entry ${id} must own exactly one path`,
	);
	const [path] = entry.paths;
	assert(
		typeof path === "string" && path.length > 0,
		`Artifact provenance ${collection} entry ${id} path must be non-empty`,
	);
	return path;
}

function uniqueWorkspace(topology, id) {
	assert(
		Array.isArray(topology?.workspaces),
		"Repository topology workspaces are required",
	);
	const matches = topology.workspaces.filter(
		(workspace) => workspace?.id === id,
	);
	assert(
		matches.length === 1,
		`Workspace ${id} must be unique in repository topology`,
	);
	return workspaceById(topology, id);
}

function resolveOutputDirectory(provenance, rootDir) {
	const path = uniqueProvenanceEntry(provenance, "outputs", "worker-dry-run");
	assert(
		/\/\*\*?$/.test(path),
		"Worker dry-run provenance must describe a directory glob",
	);
	return resolve(rootDir, path.replace(/\/\*\*?$/, ""));
}

async function scan(path, unresolvedPrivateImports, failures) {
	const entries = await readdir(path, { withFileTypes: true });
	for (const entry of entries) {
		const target = resolve(path, entry.name);
		if (entry.isDirectory())
			await scan(target, unresolvedPrivateImports, failures);
		else if (/\.(?:js|mjs|cjs)$/.test(entry.name)) {
			const source = await readFile(target, "utf8");
			if (unresolvedPrivateImports.some((name) => source.includes(name))) {
				failures.push(target);
			}
		}
	}
}

export async function checkWorkerBundle({ rootDir = repositoryRoot } = {}) {
	const provenance = loadArtifactProvenance(rootDir);
	const topology = loadTopology(rootDir);
	const worker = uniqueWorkspace(topology, "worker");
	assert(
		Array.isArray(worker.dependencies),
		"Worker workspace dependencies are required",
	);
	const unresolvedPrivateImports = worker.dependencies.map((dependency) => {
		const workspace = uniqueWorkspace(topology, dependency);
		assert(
			workspace.private === true,
			`Worker dependency ${dependency} must be a private workspace`,
		);
		assert(
			typeof workspace.name === "string" && workspace.name.length > 0,
			`Worker dependency ${dependency} package name is required`,
		);
		return workspace.name;
	});
	const outputDir = resolveOutputDirectory(provenance, rootDir);
	if (!existsSync(outputDir)) {
		throw new Error(
			`Worker bundle output directory does not exist: ${outputDir}. ` +
				"Run the worker bundle build step first (e.g., npm run worker:dry-run).",
		);
	}
	const failures = [];
	await scan(outputDir, unresolvedPrivateImports, failures);
	return { failures, outputDir, unresolvedPrivateImports };
}

const isCli =
	process.argv[1] !== undefined &&
	import.meta.url === pathToFileURL(resolve(process.argv[1])).href;

if (isCli) {
	try {
		const result = await checkWorkerBundle();
		if (result.failures.length > 0) {
			console.error(
				`Worker bundle contains private workspace imports:\n${result.failures.join("\n")}`,
			);
			process.exitCode = 1;
		} else {
			console.log(
				"Worker bundle contains no unresolved private workspace imports.",
			);
		}
	} catch (error) {
		console.error(`check-worker-bundle: ${error.message}`);
		process.exitCode = 1;
	}
}

import { execFileSync } from "node:child_process";

try {
	execFileSync("mise", ["exec", "hk", "--", "hk", "install", "--mise"], {
		stdio: "inherit",
	});
} catch (error) {
	if (error?.code === "ENOENT") {
		console.warn(
			"mise is not installed; skipping hk hook installation. See CONTRIBUTING.md.",
		);
	} else {
		console.warn("hk hook installation failed; continuing npm install.");
	}
}

const fs = require("node:fs");
const path = require("node:path");

/** Return the emitted dist output for manifests that publish a dist subtree. */
function buildOutputs(packageJson) {
	const files = Array.isArray(packageJson.files) ? packageJson.files : [];
	const publishesDist = files.some((entry) => {
		if (typeof entry !== "string") return false;
		const normalized = entry.replace(/^\.\//, "");
		return normalized === "dist" || normalized.startsWith("dist/");
	});
	return publishesDist ? ["{projectRoot}/dist"] : [];
}

/** Keep package build inputs and cache policy explicit in the Nx graph. */
function buildTarget(packageJson) {
	const name = packageJson.name;
	if (name === "hevy-mcp") {
		return {
			cache: false,
			inputs: ["nodeBuildInputs"],
			outputs: buildOutputs(packageJson),
		};
	}
	if (name === "@chrisdoc/hevy-cli") {
		return {
			cache: true,
			inputs: ["cliBuildInputs"],
			outputs: buildOutputs(packageJson),
		};
	}
	return {
		cache: true,
		inputs: ["packageBuildInputs"],
		outputs: buildOutputs(packageJson),
	};
}

module.exports = {
	name: "hevy-mcp-project-metadata",
	buildOutputs,
	buildTarget,
	createNodes: [
		"packages/*/package.json",
		(configFiles, _options, context) =>
			configFiles.map((configFile) => {
				const packageJson = JSON.parse(
					fs.readFileSync(path.join(context.workspaceRoot, configFile), "utf8"),
				);
				return [
					configFile,
					{
						projects: {
							[path.posix.dirname(configFile)]: {
								targets: { build: buildTarget(packageJson) },
							},
						},
					},
				];
			}),
	],
};

