	workspaceByName,
} from "./repository-control-plane.mjs";

const execFileAsync = promisify(execFile);
const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sinceIndex = process.argv.indexOf("--since");
const since = sinceIndex >= 0 ? process.argv[sinceIndex + 1] : "origin/main";

if (!since) throw new Error("Missing value for --since");

const topology = loadTopology(root);
const releaseTriggerFiles = new Map(
	topology.release.triggers.map((trigger) => [
		trigger.path,
		workspaceById(topology, trigger.workspace).name,
	]),
);
const releaseBumps = new Set(["patch", "minor", "major"]);

const { stdout } = await execFileAsync(
	"git",
	["diff", "--name-only", "--diff-filter=ACMRD", `${since}...HEAD`],
	{ cwd: root },
);
const changedFiles = stdout.trim().split("\n").filter(Boolean);

async function readPackageName(packagePath) {
	const manifestPath = `${packagePath}/package.json`;
	let contents;

	try {
		contents = await readFile(resolve(root, manifestPath), "utf8");
	} catch {
		try {
			const result = await execFileAsync(
				"git",
				["show", `${since}:${manifestPath}`],
				{ cwd: root },
			);
			contents = result.stdout;
		} catch {
			return undefined;
		}
	}

	try {
		const packageJson = JSON.parse(contents);
		return typeof packageJson.name === "string" ? packageJson.name : undefined;
	} catch {
		return undefined;
	}
}

const changedPackagePaths = new Set();
for (const file of changedFiles) {
	const match = file.match(/^packages\/([^/]+)(?:\/|$)/);
	if (match) changedPackagePaths.add(`packages/${match[1]}`);
}

const changedPackages = new Map();
for (const path of changedPackagePaths) {
	const packageName = await readPackageName(path);
	if (packageName) changedPackages.set(path, packageName);
}
for (const file of changedFiles) {
	const packageName = releaseTriggerFiles.get(file);
	if (packageName) changedPackages.set(file, packageName);
}

if (changedPackages.size === 0) {
	console.log("No workspace package changes require a package changeset.");
	process.exit(0);
}

const { stdout: changesetDiff } = await execFileAsync(
	"git",
	[
		"diff",
		"--name-status",
		"--find-renames",
		`${since}...HEAD`,
		"--",
		".changeset",
	],
	{ cwd: root },
);
const changedChangesetFiles = changesetDiff
	.trim()
	.split("\n")
	.filter(Boolean)
	.flatMap((line) => {
		const [status, sourcePath, destinationPath] = line.split("\t");
		if (status === "A" || status === "M") return [sourcePath];
		if (status.startsWith("R") && status !== "R100") {
			return [destinationPath];
		}
		return [];
	})
	.filter((file) => /^\.changeset\/[^/]+\.md$/.test(file));

const changesetReleases = new Set();
const emptyChangesetFiles = [];
let changedChangesetCount = 0;
for (const file of changedChangesetFiles) {
	let contents;
	try {
		contents = await readFile(resolve(root, file), "utf8");
	} catch {
		continue;
	}
	changedChangesetCount += 1;
	const fileReleases = new Set();
	const frontmatter = contents.match(/^---\s*\n([\s\S]*?)\n---/);
	if (frontmatter) {
		for (const line of frontmatter[1].split("\n")) {
			const match = line.match(
				/^\s*(?:"([^"]+)"|'([^']+)'|([@A-Za-z0-9._/-]+))\s*:\s*([A-Za-z]+)\s*$/,
			);
			if (!match) continue;
			const packageName = match[1] ?? match[2] ?? match[3];
			const bump = match[4];
			if (!releaseBumps.has(bump)) continue;
			fileReleases.add(packageName);
			changesetReleases.add(packageName);
		}
	}
	if (fileReleases.size === 0) emptyChangesetFiles.push(file);
}

if (changedChangesetCount === 0) {
	throw new Error(
		`Changed workspace packages need a changeset added or modified by this branch:\n${[...changedPackages.entries()].map(([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
	);
}

if (emptyChangesetFiles.length > 0) {
	throw new Error(
		`Empty Changesets cannot accompany release-triggering changes:\n${emptyChangesetFiles.map((file) => `- ${file}`).join("\n")}\nRelease-triggering changes require non-empty bumps:\n${[...changedPackages.entries()].map(([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
	);
}

const missing = [...changedPackages.entries()]
	.filter(([, packageName]) => !changesetReleases.has(packageName))
	.map(([path, packageName]) => `${path} -> ${packageName}`);

if (missing.length > 0) {
	throw new Error(
		`Changed workspace packages need a changeset naming the same package:\n${missing.map((entry) => `- ${entry}`).join("\n")}`,
	);
}

function getTransitiveConsumers(packageName) {
	let workspace;
	try {
		workspace = workspaceByName(topology, packageName);
	} catch {
		return [];
	}
	return releaseConsumers(topology, workspace.id).map(
		(consumer) => workspaceById(topology, consumer).name,
	);
}

const cascadeRoots = topology.release.bundles.map(
	(bundle) => workspaceById(topology, bundle.workspace).name,
);
const incompleteCascades = cascadeRoots
	.filter((packageName) => changesetReleases.has(packageName))
	.map((packageName) => ({
		packageName,
		missing: getTransitiveConsumers(packageName).filter(
			(consumer) => !changesetReleases.has(consumer),
		),
	}))
	.filter(({ missing }) => missing.length > 0);

if (incompleteCascades.length > 0) {
	throw new Error(
		`Bundled release cascades must include every transitive shipped consumer with at least a patch bump:\n${incompleteCascades
			.map(
				({ packageName, missing }) =>
					`- ${packageName} -> missing ${missing.join(", ")}`,
			)
			.join("\n")}`,
	);
}

const allowedReleases = new Set();
for (const packageName of changedPackages.values()) {
	allowedReleases.add(packageName);
	for (const consumer of getTransitiveConsumers(packageName)) {
		allowedReleases.add(consumer);
	}
}
const unrelatedReleases = [...changesetReleases].filter(
	(packageName) => !allowedReleases.has(packageName),
);
if (unrelatedReleases.length > 0) {
	throw new Error(
		`Changesets must not couple unrelated package releases:\n${unrelatedReleases
			.map((packageName) => `- ${packageName}`)
			.join("\n")}`,
	);
}

console.log(
	`Package changeset coverage passed for ${changedPackages.size} workspace package(s).`,
);

#!/usr/bin/env node
/**
 * OpenAPI Spec Script
 *
 * Fetches the OpenAPI spec from Hevy's API and applies fixes for known issues.
 * Run with: pnpm run openapi
 */
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import pkg from "abstract-syntax-tree";

const SPEC_FILE = "openapi-spec.json";
const HEVY_SWAGGER_URL = "https://api.hevyapp.com/docs/swagger-ui-init.js";

/**
 * Fix known OpenAPI spec issues from the upstream Hevy API.
 */
export function fixOpenAPISpec(spec) {
	const fixed = JSON.parse(JSON.stringify(spec));

	console.log("Applying fixes...\n");

	fixInvalidRequiredProperties(fixed.components?.schemas || {});
	fixInvalidEnumTypes(fixed.components?.schemas || {});
	fixRefSiblings(fixed.components?.schemas || {});
	fixMissingParameterSchemas(fixed.paths || {});
	fixInvalidExamples(fixed.components?.schemas || {});
	fixRoutineRestSecondsType(fixed.components?.schemas || {});

	if (!fixed.servers || fixed.servers.length === 0) {
		fixed.servers = [
			{ url: "https://api.hevyapp.com", description: "Hevy API" },
		];
		console.log("  Fixed: Added missing servers array");
	}

	fixMissingGlobalTags(fixed);
	generateOperationIds(fixed.paths || {});

	return fixed;
}

/**
 * Keep the repository-owned Routine read contract aligned with the API.
 * Upstream currently describes this field inconsistently as a string even
 * though responses contain an integer and the write schemas already use one.
 */
function fixRoutineRestSecondsType(schemas) {
	const restSeconds =
		schemas.Routine?.properties?.exercises?.items?.properties?.rest_seconds;
	if (!restSeconds) return;

	const previousType = restSeconds.type;
	const previousExample = restSeconds.example;
	restSeconds.type = "integer";

	if (
		typeof restSeconds.example === "string" &&
		/^-?\d+$/.test(restSeconds.example)
	) {
		restSeconds.example = Number(restSeconds.example);
	} else if (
		restSeconds.example !== undefined &&
		(!Number.isInteger(restSeconds.example) ||
			typeof restSeconds.example !== "number")
	) {
		delete restSeconds.example;
	}

	if (
		previousType !== restSeconds.type ||
		previousExample !== restSeconds.example
	) {
		console.log(
			"  Fixed: schemas.Routine...rest_seconds - enforced integer type and numeric example",
		);
	}
}

export function validateOpenAPISpec(spec) {
	const restSeconds =
		spec.components?.schemas?.Routine?.properties?.exercises?.items?.properties
			?.rest_seconds;
	if (!restSeconds) {
		throw new Error(
			"Routine.exercises[].rest_seconds field is missing from the OpenAPI spec",
		);
	}
	if (restSeconds.type !== "integer") {
		throw new Error(
			"Routine.exercises[].rest_seconds must remain an OpenAPI integer",
		);
	}
	if (
		restSeconds.example !== undefined &&
		(typeof restSeconds.example !== "number" ||
			!Number.isInteger(restSeconds.example))
	) {
		throw new Error(
			"Routine.exercises[].rest_seconds.example must be an integer when present",
		);
	}
}

/**
 * Fix schemas with "required": true on properties.
 */
function fixInvalidRequiredProperties(schemas, path = "schemas") {
	for (const [schemaName, schema] of Object.entries(schemas)) {
		if (schema && typeof schema === "object") {
			fixSchemaRequired(schema, `${path}.${schemaName}`);
		}
	}
}

function fixSchemaRequired(schema, path = "") {
	if (!schema || typeof schema !== "object") return;

	if (schema.properties && typeof schema.properties === "object") {
		const requiredProps = [];

		for (const [propName, propSchema] of Object.entries(schema.properties)) {
			if (propSchema && typeof propSchema === "object") {
				if (propSchema.required === true) {
					requiredProps.push(propName);
					delete propSchema.required;
					console.log(
						`  Fixed: ${path}.properties.${propName} - moved "required: true" to schema level`,
					);
				}
				fixSchemaRequired(propSchema, `${path}.properties.${propName}`);
			}
		}

		if (requiredProps.length > 0) {
			if (!schema.required) schema.required = [];
			schema.required.push(...requiredProps);
			schema.required = [...new Set(schema.required)];
		}
	}

	if (schema.items) fixSchemaRequired(schema.items, `${path}.items`);

	for (const keyword of ["allOf", "oneOf", "anyOf"]) {
		if (Array.isArray(schema[keyword])) {
			schema[keyword].forEach((subSchema, i) => {
				fixSchemaRequired(subSchema, `${path}.${keyword}[${i}]`);
			});
		}
	}

	if (
		schema.additionalProperties &&
		typeof schema.additionalProperties === "object"
	) {
		fixSchemaRequired(
			schema.additionalProperties,
			`${path}.additionalProperties`,
		);
	}
}

/**
 * Fix invalid "type": "enum" schemas.
 */
function fixInvalidEnumTypes(schemas) {
	for (const [schemaName, schema] of Object.entries(schemas)) {
		if (schema && schema.type === "enum" && Array.isArray(schema.enum)) {
			const firstValue = schema.enum[0];
			const inferredType = typeof firstValue === "number" ? "number" : "string";
			schema.type = inferredType;
			console.log(
				`  Fixed: schemas.${schemaName} - changed "type": "enum" to "type": "${inferredType}"`,
			);
		}
	}
}

/**
 * Fix $ref siblings - wrap in allOf.
 */
function fixRefSiblings(schemas) {
	for (const [schemaName, schema] of Object.entries(schemas)) {
		if (schema && typeof schema === "object") {
			fixRefSiblingsRecursive(schema, `schemas.${schemaName}`);
		}
	}
}

function fixRefSiblingsRecursive(obj, path = "") {
	if (!obj || typeof obj !== "object") return;

	if (obj.properties) {
		for (const [propName, propSchema] of Object.entries(obj.properties)) {
			if (propSchema && typeof propSchema === "object") {
				if (propSchema.$ref && Object.keys(propSchema).length > 1) {
					const ref = propSchema.$ref;
					const otherProps = { ...propSchema };
					delete otherProps.$ref;
					obj.properties[propName] = { allOf: [{ $ref: ref }, otherProps] };
					console.log(
						`  Fixed: ${path}.properties.${propName} - wrapped $ref with siblings in allOf`,
					);
				} else {
					fixRefSiblingsRecursive(propSchema, `${path}.properties.${propName}`);
				}
			}
		}
	}

	if (obj.items) fixRefSiblingsRecursive(obj.items, `${path}.items`);

	for (const keyword of ["allOf", "oneOf", "anyOf"]) {
		if (Array.isArray(obj[keyword])) {
			obj[keyword].forEach((subSchema, i) => {
				fixRefSiblingsRecursive(subSchema, `${path}.${keyword}[${i}]`);
			});
		}
	}
}

/**
 * Fix missing schema on parameters.
 */
function fixMissingParameterSchemas(paths) {
	for (const [pathName, pathItem] of Object.entries(paths)) {
		for (const method of ["get", "post", "put", "patch", "delete"]) {
			const operation = pathItem[method];
			if (!operation?.parameters) continue;

			for (const param of operation.parameters) {
				if (!param.schema && !param.content) {
					if (param.in === "header") {
						param.schema = { type: "string", format: "uuid" };
					} else {
						param.schema = { type: "string" };
					}
					console.log(
						`  Fixed: paths.${pathName}.${method}.parameters - added missing schema to "${param.name}" ${param.in} param`,
					);
				}
			}
		}
	}
}

/**
 * Fix invalid examples in schemas.
 */
function fixInvalidExamples(schemas) {
	const postWorkoutsSet = schemas.PostWorkoutsRequestSet;
	if (postWorkoutsSet?.properties?.rpe?.example === null) {
		delete postWorkoutsSet.properties.rpe.example;
		console.log(
			"  Fixed: schemas.PostWorkoutsRequestSet.properties.rpe - removed invalid null example",
		);
	}
}

/**
 * Add missing global tags from operations.
 */
function fixMissingGlobalTags(spec) {
	const usedTags = new Set();

	for (const pathItem of Object.values(spec.paths || {})) {
		for (const method of ["get", "post", "put", "patch", "delete"]) {
			const operation = pathItem[method];
			if (operation?.tags) {
				for (const tag of operation.tags) usedTags.add(tag);
			}
		}
	}

	if (!spec.tags) spec.tags = [];
	const existingTags = new Set(spec.tags.map((t) => t.name));

	for (const tag of usedTags) {
		if (typeof tag !== "string") {
			console.warn(
				`  Warning: Skipping invalid non-string tag: ${JSON.stringify(tag)}`,
			);
			continue;
		}
		if (!existingTags.has(tag)) {
			spec.tags.push({ name: tag, description: `${tag} operations` });
			console.log(`  Fixed: Added missing global tag "${tag}"`);
		}
	}
}

/**
 * Generate operationIds matching Kubb's expected format.
 * e.g., GET /v1/workouts/{workoutId} -> getV1WorkoutsWorkoutid
 */
function generateOperationIds(paths) {
	for (const [pathName, pathItem] of Object.entries(paths)) {
		for (const method of ["get", "post", "put", "patch", "delete"]) {
			const operation = pathItem[method];
			if (!operation || operation.operationId) continue;

			const pathParts = pathName
				.replace(/^\//, "")
				.replace(/\{(\w+)\}/g, (_, param) => param.toLowerCase())
				.split("/")
				.map((part, i) => {
					const camelCase = part.replace(/_(\w)/g, (_, c) => c.toUpperCase());
					return i === 0
						? camelCase
						: camelCase.charAt(0).toUpperCase() + camelCase.slice(1);
				})
				.join("");

			operation.operationId =
				method + pathParts.charAt(0).toUpperCase() + pathParts.slice(1);
			console.log(
				`  Fixed: paths.${pathName}.${method} - generated operationId "${operation.operationId}"`,
			);
		}
	}
}

/**
 * Fetch the OpenAPI spec from Hevy's swagger-ui-init.js file
 */
async function fetchSpecFromHevy() {
	console.log("Fetching OpenAPI spec from Hevy API...\n");

	const response = await fetch(HEVY_SWAGGER_URL);
	if (!response.ok) {
		throw new Error(`HTTP error! Status: ${response.status}`);
	}

	const jsContent = await response.text();
	const ast = pkg.parse(jsContent);

	const optionsNode = pkg.find(ast, 'VariableDeclarator[id.name="options"]')[0];
	if (!optionsNode?.init?.properties) {
		throw new Error("options variable not found in swagger-ui-init.js");
	}

	const swaggerDocProperty = optionsNode.init.properties.find(
		(prop) => prop.key.value === "swaggerDoc",
	);
	if (!swaggerDocProperty) {
		throw new Error("swaggerDoc property not found in options");
	}

	const swaggerDocCode = pkg.generate(swaggerDocProperty.value, {
		tabs: true,
	});
	return JSON.parse(swaggerDocCode);
}

async function main() {
	try {
		const spec = await fetchSpecFromHevy();
		const fixedSpec = fixOpenAPISpec(spec);
		validateOpenAPISpec(fixedSpec);

		writeFileSync(SPEC_FILE, JSON.stringify(fixedSpec, null, "\t"));
		console.log(`\n✓ OpenAPI spec saved to ${SPEC_FILE}`);
	} catch (error) {
		console.error("Error:", error.message);
		process.exit(1);
	}
}

if (
	process.argv[1] &&
	fileURLToPath(import.meta.url) === resolve(process.argv[1])
) {
	void main();
}

#!/usr/bin/env node
import {
	cp,
	mkdtemp,
	mkdir,
	readFile,
	readdir,
	rm,
	stat,
	writeFile,
} from "node:fs/promises";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { spawn } from "node:child_process";
import { createRequire } from "node:module";
import { fixOpenAPISpec, validateOpenAPISpec } from "./openapi-spec.js";

const require = createRequire(import.meta.url);
const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const clientRoot = resolve(repositoryRoot, "packages/hevy-client");
const generatedRelative = "src/generated";
const generatedRoot = resolve(clientRoot, generatedRelative);
const curatedBarrels = ["src/types.ts", "src/schemas.ts"];
const DEFAULT_COMMAND_TIMEOUT_MS = 120_000;
const DEFAULT_COMMAND_KILL_SIGNAL = "SIGTERM";
const SIGKILL_GRACE_PERIOD_MS = 2_000;

async function collectFiles(directory) {
	try {
		const entries = await readdir(directory, { withFileTypes: true });
		const files = [];
		for (const entry of entries) {
			const path = join(directory, entry.name);
			if (entry.isDirectory()) files.push(...(await collectFiles(path)));
			else files.push(path);
		}
		return files;
	} catch (error) {
		if (error?.code === "ENOENT") return [];
		throw error;
	}
}

function relativePath(root, path) {
	return relative(root, path).replaceAll("\\", "/");
}

export function isNodeModulesPath(path) {
	return path.split(/[\\/]+/).includes("node_modules");
}

/**
 * Compare two generated output trees without mutating either tree.
 *
 * The result is intentionally a list rather than a boolean so CI output
 * identifies the exact generated file that needs review.
 */
export async function compareDirectoryTrees(expectedRoot, actualRoot) {
	const expectedFiles = new Map(
		(await collectFiles(expectedRoot)).map((path) => [
			relativePath(expectedRoot, path),
			path,
		]),
	);
	const actualFiles = new Map(
		(await collectFiles(actualRoot)).map((path) => [
			relativePath(actualRoot, path),
			path,
		]),
	);
	const differences = [];
	const paths = new Set([...expectedFiles.keys(), ...actualFiles.keys()]);

	for (const path of [...paths].sort((left, right) =>
		left.localeCompare(right),
	)) {
		const expectedPath = expectedFiles.get(path);
		const actualPath = actualFiles.get(path);
		if (!expectedPath) {
			differences.push(`unexpected generated file: ${path}`);
			continue;
		}
		if (!actualPath) {
			differences.push(`missing generated file: ${path}`);
			continue;
		}

		const [expected, actual] = await Promise.all([
			readFile(expectedPath),
			readFile(actualPath),
		]);
		if (!expected.equals(actual)) {
			differences.push(`generated file differs: ${path}`);
		}
	}

	return differences;
}

/**
 * Return every file under a repository-root `src` directory. The repository
 * intentionally has no runtime root source tree; a non-empty result means a
 * generator escaped its package output closure.
 */
export async function findForbiddenRootSourceFiles(root) {
	const sourceRoot = resolve(root, "src");
	try {
		const sourceStats = await stat(sourceRoot);
		if (!sourceStats.isDirectory()) return ["src"];
	} catch (error) {
		if (error?.code === "ENOENT") return [];
		throw error;
	}

	const files = await collectFiles(sourceRoot);
	return files.length > 0
		? files.map((path) => relativePath(root, path)).sort()
		: ["src"];
}

function generatedTargetCandidates(specifier) {
	const target = specifier.slice("./generated/".length);
	if (target.includes("..")) return [];
	const candidates = [target];
	if (target.endsWith(".js")) {
		candidates.push(target.slice(0, -3) + ".ts");
		candidates.push(target.slice(0, -3) + ".json");
	}
	return candidates;
}

/**
 * Ensure curated public barrels only reference generated files that exist.
 * This keeps an upstream endpoint/schema change from silently leaving a
 * broken package API after regeneration.
 */
export async function findCuratedBarrelDrift(packageRoot) {
	const generatedDirectory = resolve(packageRoot, generatedRelative);
	const failures = [];
	const importPattern = /from\s+["'](\.\/generated\/[^"']+)["']/g;

	for (const barrel of curatedBarrels) {
		const barrelPath = resolve(packageRoot, barrel);
		let source;
		try {
			source = await readFile(barrelPath, "utf8");
		} catch (error) {
			if (error?.code === "ENOENT") {
				failures.push(`missing curated barrel: ${barrel}`);
				continue;
			}
			throw error;
		}

		for (const match of source.matchAll(importPattern)) {
			const specifier = match[1];
			const candidates = generatedTargetCandidates(specifier);
			let targetExists = false;
			for (const candidate of candidates) {
				try {
					await stat(resolve(generatedDirectory, candidate));
					targetExists = true;
					break;
				} catch {
					// Try the next extension candidate.
				}
			}
			if (!targetExists) {
				failures.push(`${barrel}: missing generated target ${specifier}`);
			}
		}
	}

	try {
		const tsc = await resolvePackageExecutable("typescript", "tsc");
		await runCommand(
			tsc.command,
			[...tsc.args, "--noEmit", "--pretty", "false", "-p", "./tsconfig.json"],
			packageRoot,
		);
	} catch (error) {
		failures.push(
			`curated barrel TypeScript check failed: ${
				error instanceof Error ? error.message : String(error)
			}`,
		);
	}

	return failures;
}

/**
 * Resolve a package's JavaScript bin entry and invoke it through Node. Calling
 * the bin entry directly avoids npm's platform-specific `.cmd`/shell shims
 * without ever interpolating arguments into a shell command.
 */
export async function resolvePackageExecutable(packageName, binName) {
	let packageJsonPath;
	try {
		packageJsonPath = require.resolve(`${packageName}/package.json`);
	} catch (error) {
		throw new Error(
			`Unable to resolve ${packageName} package metadata: ${
				error instanceof Error ? error.message : String(error)
			}`,
			{ cause: error },
		);
	}

	let packageJson;
	try {
		packageJson = JSON.parse(await readFile(packageJsonPath, "utf8"));
	} catch (error) {
		throw new Error(
			`Unable to read ${packageName} package metadata: ${
				error instanceof Error ? error.message : String(error)
			}`,
			{ cause: error },
		);
	}
	const packageBin = packageJson.bin;
	const binary =
		typeof packageBin === "string"
			? packageBin
			: (packageBin?.[binName] ?? packageBin?.[packageName]);

	if (typeof binary !== "string" || binary.length === 0) {
		throw new Error(
			`Package ${packageName} does not declare a ${binName} executable`,
		);
	}

	return {
		command: process.execPath,
		args: [resolve(dirname(packageJsonPath), binary)],
	};
}

function formatCommand(command, args) {
	return [command, ...args]
		.map((part) => JSON.stringify(String(part)))
		.join(" ");
}

export function runCommand(
	command,
	args,
	cwd,
	{
		timeout = DEFAULT_COMMAND_TIMEOUT_MS,
		killSignal = DEFAULT_COMMAND_KILL_SIGNAL,
	} = {},
) {
	const commandTimeout =
		Number.isFinite(timeout) && timeout > 0
			? Math.floor(timeout)
			: DEFAULT_COMMAND_TIMEOUT_MS;
	const displayCommand = formatCommand(command, args);

	return new Promise((resolvePromise, reject) => {
		let output = "";
		let timedOut = false;
		let settled = false;
		let timeoutHandle;
		let gracePeriodHandle;

		const finish = (callback) => {
			if (settled) return;
			settled = true;
			if (timeoutHandle) clearTimeout(timeoutHandle);
			if (gracePeriodHandle) clearTimeout(gracePeriodHandle);
			callback();
		};
		const rejectWithMessage = (status, cause) => {
			finish(() =>
				reject(
					new Error(
						[`${displayCommand} failed: ${status}`, output.trim()]
							.filter(Boolean)
							.join("\n"),
						{ cause },
					),
				),
			);
		};

		let child;
		try {
			child = spawn(command, args, {
				cwd,
				stdio: ["ignore", "pipe", "pipe"],
				shell: false,
				timeout: commandTimeout,
				killSignal,
			});
		} catch (error) {
			rejectWithMessage(
				`could not start: ${error instanceof Error ? error.message : String(error)}`,
				error,
			);
			return;
		}

		timeoutHandle = setTimeout(
			() => {
				if (child.exitCode === null && child.signalCode === null) {
					timedOut = true;
					child.kill(killSignal);

					if (killSignal !== "SIGKILL") {
						gracePeriodHandle = setTimeout(() => {
							if (child.exitCode === null && child.signalCode === null) {
								child.kill("SIGKILL");
							}
						}, SIGKILL_GRACE_PERIOD_MS);
					}
				}
			},
			Math.max(1, commandTimeout - 1),
		);
		child.stdout.on("data", (chunk) => {
			output += chunk;
		});
		child.stderr.on("data", (chunk) => {
			output += chunk;
		});
		child.once("error", (error) => {
			const code = error?.code ? ` (${error.code})` : "";
			rejectWithMessage(`could not start${code}: ${error.message}`, error);
		});
		child.once("close", (code, signal) => {
			if (timedOut) {
				rejectWithMessage(
					`timed out after ${commandTimeout}ms; sent ${String(killSignal)}`,
				);
				return;
			}
			if (code === 0) {
				finish(resolvePromise);
				return;
			}
			rejectWithMessage(
				signal ? `terminated by signal ${signal}` : `exited with code ${code}`,
			);
		});
	});
}

async function readNormalizedSpec() {
	const specPath = resolve(repositoryRoot, "openapi-spec.json");
	const source = JSON.parse(await readFile(specPath, "utf8"));
	const normalized = fixOpenAPISpec(source);
	validateOpenAPISpec(normalized);
	return {
		normalized,
		normalizationDrift: JSON.stringify(source) !== JSON.stringify(normalized),
	};
}

async function createFixtureRepository(normalizedSpec) {
	const fixtureParent = resolve(repositoryRoot, "node_modules/.cache");
	await mkdir(fixtureParent, { recursive: true });
	const root = await mkdtemp(join(fixtureParent, "generated-client-check-"));
	try {
		const fixtureClient = resolve(root, "packages/hevy-client");
		await cp(clientRoot, fixtureClient, {
			recursive: true,
			filter: (path) => !isNodeModulesPath(path),
		});
		await rm(resolve(fixtureClient, generatedRelative), {
			recursive: true,
			force: true,
		});
		await cp(
			resolve(repositoryRoot, "tsconfig.base.json"),
			resolve(root, "tsconfig.base.json"),
		);
		await writeFile(
			resolve(root, "openapi-spec.json"),
			JSON.stringify(normalizedSpec, null, "\t"),
		);
		return { root, client: fixtureClient };
	} catch (error) {
		await rm(root, { recursive: true, force: true });
		throw error;
	}
}

/**
 * Regenerate the checked contract in a temporary repository copy. Running
 * Kubb with the checked-in config is important: a future path regression must
 * create the fixture's root `src/` tree and fail this check.
 */
export async function checkGeneratedClient() {
	const { normalized, normalizationDrift } = await readNormalizedSpec();
	let fixture;
	try {
		fixture = await createFixtureRepository(normalized);
		const kubb = await resolvePackageExecutable("@kubb/cli", "kubb");
		const prettier = await resolvePackageExecutable("prettier", "prettier");
		await runCommand(
			kubb.command,
			[...kubb.args, "generate", "--config", "./kubb.config.ts"],
			fixture.client,
		);
		await runCommand(
			prettier.command,
			[...prettier.args, "--ignore-unknown", "--write", generatedRelative],
			fixture.client,
		);

		const failures = [];
		if (normalizationDrift) {
			failures.push(
				"checked OpenAPI spec is not normalized; run npm run openapi for a reviewed refresh",
			);
		}
		const rootSourceFiles = await findForbiddenRootSourceFiles(fixture.root);
		if (rootSourceFiles.length > 0) {
			failures.push(
				`forbidden root src creation: ${rootSourceFiles.join(", ")}`,
			);
		}
		failures.push(
			...(await compareDirectoryTrees(
				generatedRoot,
				resolve(fixture.client, generatedRelative),
			)),
		);
		failures.push(...(await findCuratedBarrelDrift(fixture.client)));

		if (failures.length > 0) {
			throw new Error(
				[
					"Generated client regeneration drift detected.",
					...failures.map((failure) => `- ${failure}`),
				].join("\n"),
			);
		}

		return { generatedFiles: (await collectFiles(generatedRoot)).length };
	} finally {
		if (fixture) {
			await rm(fixture.root, { recursive: true, force: true });
		}
	}
}

if (
	process.argv[1] &&
	fileURLToPath(import.meta.url) === resolve(process.argv[1])
) {
	try {
		const result = await checkGeneratedClient();
		console.log(
			`Generated client is up to date (${result.generatedFiles} files); no root src tree was created.`,
		);
	} catch (error) {
		console.error(error instanceof Error ? error.message : error);
		process.exitCode = 1;
	}
}

import { existsSync, readFileSync, readdirSync } from "node:fs";
import { resolve } from "node:path";
import { loadControlPlane, repositoryRoot } from "./control-plane-models.mjs";

const selectorKinds = new Set([
	"vitest",
	"vitest-worker-config",
	"npm-pack-smoke",
	"workspace-test",
	"control-plane",
	"changeset-status",
	"typescript",
	"repository-check",
	"package-build",
	"wrangler-dry-run",
	"manifest-drift",
	"vitest-live",
	"worker-live",
	"vitest-integration",
	"launcher-canary",
	"docker-smoke",
	"generated-output-closure",
	"node-test",
]);
const gateKinds = new Set([
	"blocking",
	"informational",
	"advisory",
	"release",
	"nightly",
]);
const mappingStatuses = new Set(["mapped", "external", "unresolved"]);
const allowedRuntimes = new Set(["neutral", "node", "workerd"]);
const allowedRoles = new Set(["client", "runtime", "server", "adapter", "cli"]);

function assert(condition, message) {
	if (!condition) throw new Error(message);
}

function assertArray(value, label) {
	assert(Array.isArray(value), label + " must be an array");
}

function assertString(value, label) {
	assert(typeof value === "string" && value.length > 0, label + " is required");
}

function assertUnique(values, label) {
	const duplicates = values.filter(
		(value, index) => values.indexOf(value) !== index,
	);
	assert(
		duplicates.length === 0,
		label + " contains duplicates: " + [...new Set(duplicates)].join(", "),
	);
}

function packageExports(packageJson) {
	if (!packageJson.exports || typeof packageJson.exports !== "object")
		return [];
	return Object.keys(packageJson.exports);
}

function loadPackageJson(rootDir, workspace) {
	const packagePath = resolve(rootDir, workspace.path, "package.json");
	assert(existsSync(packagePath), workspace.path + "/package.json is missing");
	return JSON.parse(readFileSync(packagePath, "utf8"));
}

function internalDependencyIds(packageJson, names) {
	const fields = [
		...(packageJson.dependencies ? Object.keys(packageJson.dependencies) : []),
		...(packageJson.devDependencies
			? Object.keys(packageJson.devDependencies)
			: []),
	];
	return [
		...new Set(
			fields.filter((name) => names.has(name)).map((name) => names.get(name)),
		),
	].sort((left, right) => left.localeCompare(right));
}

function validateReleaseGraph(topology) {
	const bundles = topology.release.bundles;
	assertUnique(
		bundles.map((bundle) => bundle.workspace),
		"release bundle workspaces",
	);
	const bundleIds = new Set(bundles.map((bundle) => bundle.workspace));
	const graph = new Map(
		bundles.map((bundle) => [bundle.workspace, bundle.consumers]),
	);
	const visiting = new Set();
	const visited = new Set();
	const visit = (id, stack) => {
		if (visiting.has(id))
			throw new Error("Release cascade cycle: " + [...stack, id].join(" -> "));
		if (visited.has(id)) return;
		visiting.add(id);
		for (const consumer of graph.get(id) || []) visit(consumer, [...stack, id]);
		visiting.delete(id);
		visited.add(id);
	};
	for (const id of bundleIds) visit(id, []);
}

export function validateTopology(rootDir, topology, artifactIds) {
	assert(topology && topology.version === 1, "topology version must be 1");
	assertString(topology.workspaceGlob, "topology.workspaceGlob");
	assert(
		topology.root?.private === true && topology.root?.orchestrator === true,
		"topology root must describe a private orchestrator",
	);
	const rootPackagePath = resolve(rootDir, "package.json");
	assert(existsSync(rootPackagePath), "root package.json is required");
	const rootPackage = JSON.parse(readFileSync(rootPackagePath, "utf8"));
	assertArray(rootPackage.workspaces, "root package workspaces");
	assert(
		JSON.stringify(rootPackage.workspaces) ===
			JSON.stringify([topology.workspaceGlob]),
		"root package workspaces must match topology workspaceGlob",
	);
	assert(
		rootPackage.private === topology.root.private,
		"root package private flag does not match topology",
	);
	assert(
		rootPackage.private === true,
		"Root orchestration package must be private",
	);
	for (const field of [
		"version",
		"main",
		"module",
		"types",
		"bin",
		"files",
		"publishConfig",
	])
		assert(
			!(field in rootPackage),
			"Root orchestration package must not declare " + field,
		);
	assertArray(topology.workspaces, "topology.workspaces");
	assertUnique(
		topology.workspaces.map((workspace) => workspace.id),
		"workspace ids",
	);
	assertUnique(
		topology.workspaces.map((workspace) => workspace.path),
		"workspace paths",
	);
	assertUnique(
		topology.workspaces.map((workspace) => workspace.name),
		"workspace names",
	);
	const ids = new Set(topology.workspaces.map((workspace) => workspace.id));
	const names = new Map(
		topology.workspaces.map((workspace) => [workspace.name, workspace.id]),
	);
	for (const workspace of topology.workspaces) {
		for (const field of ["id", "path", "name", "runtime", "role"])
			assertString(
				workspace[field],
				"workspace " + (workspace.id || "?") + "." + field,
			);
		assert(
			allowedRuntimes.has(workspace.runtime),
			workspace.id + " has unknown runtime",
		);
		assert(
			allowedRoles.has(workspace.role),
			workspace.id + " has unknown role",
		);
		assert(
			typeof workspace.private === "boolean",
			workspace.id + " private must be boolean",
		);
		assert(
			typeof workspace.publishable === "boolean",
			workspace.id + " publishable must be boolean",
		);
		assert(
			!workspace.publishable || !workspace.private,
			workspace.id + " publishable workspaces must be non-private",
		);
		assertArray(workspace.exports, workspace.id + ".exports");
		assertArray(workspace.dependencies, workspace.id + ".dependencies");
		assertArray(workspace.artifacts, workspace.id + ".artifacts");
		assertUnique(workspace.dependencies, workspace.id + " dependencies");
		assertUnique(workspace.artifacts, workspace.id + " artifacts");
		for (const dependency of workspace.dependencies)
			assert(
				ids.has(dependency),
				workspace.id + " references unknown dependency " + dependency,
			);
		assert(
			workspace.boundary && typeof workspace.boundary === "object",
			workspace.id + ".boundary is required",
		);
		assertArray(
			workspace.boundary.forbidden,
			workspace.id + ".boundary.forbidden",
		);
		for (const pattern of workspace.boundary.forbidden)
			assertString(pattern, workspace.id + ".boundary.forbidden pattern");
		assert(
			typeof workspace.boundary.rejectBuiltins === "boolean",
			workspace.id + ".boundary.rejectBuiltins must be boolean",
		);
		assert(
			typeof workspace.boundary.rejectDynamicImports === "boolean",
			workspace.id + ".boundary.rejectDynamicImports must be boolean",
		);
		assert(
			workspace.boundary.allowed &&
				typeof workspace.boundary.allowed === "object",
			workspace.id + ".boundary.allowed is required",
		);
		for (const packageName of Object.keys(workspace.boundary.allowed)) {
			const subpaths = workspace.boundary.allowed[packageName];
			assert(
				names.has(packageName),
				workspace.id +
					".boundary.allowed references unknown package " +
					packageName,
			);
			assert(
				names.get(packageName) &&
					workspace.dependencies.includes(names.get(packageName)),
				workspace.id + ".boundary.allowed package is not a declared dependency",
			);
			assertArray(subpaths, workspace.id + ".boundary.allowed." + packageName);
			for (const subpath of subpaths)
				assert(
					typeof subpath === "string",
					workspace.id + ".boundary.allowed subpaths must be strings",
				);
		}
		for (const artifact of workspace.artifacts)
			assert(
				artifactIds.has(artifact),
				workspace.id + " references unknown artifact " + artifact,
			);
		const packageJson = loadPackageJson(rootDir, workspace);
		assert(
			packageJson.name === workspace.name,
			workspace.path + "/package.json name does not match topology",
		);
		assert(
			(packageJson.private === true) === workspace.private,
			workspace.path + "/package.json private flag does not match topology",
		);
		assert(
			workspace.publishable === (packageJson.private !== true),
			workspace.path + "/package.json publishability does not match topology",
		);
		assert(
			JSON.stringify(packageExports(packageJson)) ===
				JSON.stringify(workspace.exports),
			workspace.path + "/package.json exports do not match topology",
		);
		assert(
			JSON.stringify(internalDependencyIds(packageJson, names)) ===
				JSON.stringify(
					[...workspace.dependencies].sort((left, right) =>
						left.localeCompare(right),
					),
				),
			workspace.path +
				"/package.json dependency direction does not match topology",
		);
	}
	const actualPaths = readdirSync(resolve(rootDir, "packages"), {
		withFileTypes: true,
	})
		.filter((entry) => entry.isDirectory())
		.map((entry) => "packages/" + entry.name)
		.sort();
	const expectedPaths = topology.workspaces
		.map((workspace) => workspace.path)
		.sort();
	assert(
		JSON.stringify(actualPaths) === JSON.stringify(expectedPaths),
		"workspace directories do not match topology",
	);
	const publishablePackages = topology.workspaces
		.filter((workspace) => workspace.publishable)
		.map((workspace) => workspace.name)
		.sort((left, right) => left.localeCompare(right));
	const nonPrivatePackages = topology.workspaces
		.filter((workspace) => workspace.private !== true)
		.map((workspace) => workspace.name)
		.sort((left, right) => left.localeCompare(right));
	assert(
		JSON.stringify(publishablePackages) === JSON.stringify(nonPrivatePackages),
		"every non-private workspace must be declared publishable",
	);
	const release = topology.release;
	assert(
		release && typeof release === "object",
		"topology.release is required",
	);
	assertArray(release.triggers, "topology.release.triggers");
	assertUnique(
		release.triggers.map((trigger) => trigger?.path),
		"release trigger paths",
	);
	for (const trigger of release.triggers) {
		assertString(trigger.path, "release trigger path");
		assert(
			ids.has(trigger.workspace),
			"release trigger references unknown workspace " + trigger.workspace,
		);
	}
	assertArray(release.bundles, "topology.release.bundles");
	for (const bundle of release.bundles) {
		assert(
			ids.has(bundle.workspace),
			"release bundle references unknown workspace " + bundle.workspace,
		);
		assertArray(bundle.consumers, "release bundle consumers");
		for (const consumer of bundle.consumers)
			assert(
				ids.has(consumer),
				"release bundle references unknown consumer " + consumer,
			);
	}
	validateReleaseGraph(topology);
	return topology;
}

export function validateArtifactProvenance(
	provenance,
	topology,
	laneIds,
	rootDir = repositoryRoot,
) {
	assert(
		provenance && provenance.version === 1,
		"artifact provenance version must be 1",
	);
	for (const field of ["sources", "generators", "outputs", "candidates"])
		assertArray(provenance[field], "artifact provenance " + field);
	const allEntries = [
		...provenance.sources,
		...provenance.generators,
		...provenance.outputs,
		...provenance.candidates,
	];
	assertUnique(
		allEntries.map((entry) => entry.id),
		"artifact provenance ids",
	);
	for (const entry of allEntries)
		assert(
			!("command" in entry) && !("credentials" in entry),
			"artifact provenance entries must not encode commands or credentials",
		);
	const sourceIds = new Set(provenance.sources.map((entry) => entry.id));
	const outputIds = new Set(provenance.outputs.map((entry) => entry.id));
	const workspaceIds = new Set(
		topology.workspaces.map((workspace) => workspace.id),
	);
	const project = JSON.parse(
		readFileSync(resolve(rootDir, "project.json"), "utf8"),
	);
	const packageJson = JSON.parse(
		readFileSync(resolve(rootDir, "package.json"), "utf8"),
	);
	const projectTargets = project.targets || {};
	const targetIds = new Set([
		...Object.keys(projectTargets),
		...Object.keys(packageJson.scripts || {}),
	]);
	const validationTargetIds = new Set([...targetIds, ...laneIds]);
	const assertTarget = (target, label) => {
		assertString(target, label);
		assert(
			validationTargetIds.has(target),
			label + " references missing producer or validation target " + target,
		);
	};
	const assertProducer = (producer, label) => {
		assert(
			producer && typeof producer === "object",
			label + " producer is required",
		);
		assertString(producer.kind, label + ".producer.kind");
		assert(
			!("command" in producer) && !("credentials" in producer),
			label + " producer must not encode commands or credentials",
		);
		if (producer.kind === "nx-target") {
			assertTarget(producer.target, label + ".producer.target");
			return;
		}
		assert(
			producer.kind === "external" &&
				typeof producer.id === "string" &&
				producer.id.length > 0,
			label + ".producer must be an Nx target or named external producer",
		);
	};
	const targetOutputPaths = (target) =>
		(projectTargets[target]?.outputs || []).map((output) =>
			String(output)
				.replaceAll("{workspaceRoot}/", "")
				.replaceAll("{projectRoot}/", ""),
		);
	const outputPathMatches = (path, targetOutput) => {
		const normalizedPath = path.replaceAll("\\", "/");
		const normalizedOutput = targetOutput
			.replaceAll("\\", "/")
			.replace(/\/\*\*$/, "")
			.replace(/\/\*$/, "");
		if (
			normalizedPath === normalizedOutput ||
			normalizedPath.startsWith(normalizedOutput + "/")
		)
			return true;
		let pattern = "^";
		for (let index = 0; index < normalizedOutput.length; index++) {
			if (normalizedOutput.startsWith("**", index)) {
				pattern += ".*";
				index++;
				continue;
			}
			if (normalizedOutput[index] === "*") {
				pattern += "[^/]*";
				continue;
			}
			pattern += normalizedOutput[index].replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
		}
		return new RegExp(pattern + "$").test(normalizedPath);
	};
	for (const source of provenance.sources) {
		assertString(source.id, "artifact source id");
		assertArray(source.paths, source.id + ".paths");
		assert(source.paths.length > 0, source.id + ".paths must not be empty");
		assertString(source.kind, source.id + ".kind");
	}
	for (const generator of provenance.generators) {
		assertString(generator.id, "artifact generator id");
		assertString(generator.kind, generator.id + ".kind");
		assert(
			!("command" in generator),
			generator.id + " must not encode commands",
		);
		assertArray(generator.inputs, generator.id + ".inputs");
		assertArray(generator.outputs, generator.id + ".outputs");
		assertArray(generator.validation, generator.id + ".validation");
		assertProducer(generator.producer, generator.id);
		assertArray(
			generator.validationTargets,
			generator.id + ".validationTargets",
		);
		assert(
			generator.validationTargets.length > 0,
			generator.id + ".validationTargets must not be empty",
		);
		for (const target of generator.validationTargets)
			assertTarget(target, generator.id + ".validationTargets");
		for (const input of generator.inputs)
			assert(
				sourceIds.has(input),
				generator.id + " references unknown source " + input,
			);
		for (const output of generator.outputs)
			assert(
				outputIds.has(output),
				generator.id + " references unknown output " + output,
			);
		for (const lane of generator.validation)
			assert(
				laneIds.has(lane),
				generator.id + " references unknown lane " + lane,
			);
	}
	for (const output of provenance.outputs) {
		assertString(output.id, "artifact output id");
		assertArray(output.paths, output.id + ".paths");
		assertString(output.kind, output.id + ".kind");
		if (output.kind !== "external")
			assert(output.paths.length > 0, output.id + ".paths must not be empty");
		assertArray(output.owners, output.id + ".owners");
		assert(output.owners.length > 0, output.id + ".owners must not be empty");
		assertArray(output.producers, output.id + ".producers");
		assert(
			output.producers.length > 0,
			output.id + ".producers must not be empty",
		);
		for (const producer of output.producers)
			assertProducer(producer, output.id);
		assertArray(output.validationTargets, output.id + ".validationTargets");
		assert(
			output.validationTargets.length > 0,
			output.id + ".validationTargets must not be empty",
		);
		for (const target of output.validationTargets)
			assertTarget(target, output.id + ".validationTargets");
		if (output.kind !== "external") {
			for (const producer of output.producers) {
				if (producer.kind !== "nx-target") continue;
				const outputs = targetOutputPaths(producer.target);
				if (outputs.length === 0) continue;
				for (const path of output.paths)
					assert(
						outputs.some((targetOutput) =>
							outputPathMatches(path, targetOutput),
						),
						output.id +
							" path " +
							path +
							" does not match producer target output " +
							producer.target,
					);
			}
		} else {
			assert(
				output.paths.length === 0 &&
					output.producers.every((producer) => producer.kind === "external"),
				output.id + " external output needs an external producer and no paths",
			);
		}
		for (const owner of output.owners)
			assert(
				laneIds.has(owner),
				output.id + " references unknown owner " + owner,
			);
	}
	for (const candidate of provenance.candidates) {
		assertString(candidate.id, "artifact candidate id");
		assertString(candidate.kind, candidate.id + ".kind");
		assert(
			!("command" in candidate) && !("credentials" in candidate),
			candidate.id + " must not encode commands or credentials",
		);
		assert(
			typeof candidate.workspace === "string" &&
				workspaceIds.has(candidate.workspace),
			candidate.id + " references unknown workspace",
		);
		assertArray(candidate.sourcePaths, candidate.id + ".sourcePaths");
		assert(
			candidate.sourcePaths.length > 0,
			candidate.id + ".sourcePaths must not be empty",
		);
		assertArray(candidate.outputs, candidate.id + ".outputs");
		assert(
			candidate.outputs.length > 0,
			candidate.id + ".outputs must not be empty",
		);
		for (const output of candidate.outputs)
			assert(
				outputIds.has(output),
				candidate.id + " references unknown output " + output,
			);
		assertArray(candidate.producers, candidate.id + ".producers");
		assert(
			candidate.producers.length > 0,
			candidate.id + ".producers must not be empty",
		);
		for (const producer of candidate.producers)
			assertProducer(producer, candidate.id);
		assertArray(
			candidate.validationTargets,
			candidate.id + ".validationTargets",
		);
		assert(
			candidate.validationTargets.length > 0,
			candidate.id + ".validationTargets must not be empty",
		);
		for (const target of candidate.validationTargets)
			assertTarget(target, candidate.id + ".validationTargets");
		if (candidate.external === true)
			assert(
				candidate.producers.every((producer) => producer.kind === "external"),
				candidate.id + " external candidate needs an external producer",
			);
		else
			assert(
				candidate.producers.every((producer) => producer.kind === "nx-target"),
				candidate.id + " non-external candidate needs Nx producers",
			);
		assertArray(candidate.validation, candidate.id + ".validation");
		for (const lane of candidate.validation)
			assert(
				laneIds.has(lane),
				candidate.id + " references unknown lane " + lane,
			);
	}
	const requiredCandidateSources = {
		"worker-bundle": [
			"packages/worker/**",
			"packages/core/**",
			"packages/hevy-client/**",
			"cloudflare.config.ts",
			"package.json",
			"package-lock.json",
			"packages/worker/package.json",
			"packages/core/package.json",
			"packages/hevy-client/package.json",
		],
		"docker-image": [
			"Dockerfile",
			"package.json",
			"package-lock.json",
			"tsconfig.base.json",
			"tsconfig.json",
			"packages/hevy-client/package.json",
			"packages/core/package.json",
			"packages/node/package.json",
			"packages/worker/package.json",
			"scripts/install-git-hooks.mjs",
			"packages/hevy-client/**",
			"packages/core/**",
			"packages/node/**",
		],
	};
	for (const [candidateId, requiredPaths] of Object.entries(
		requiredCandidateSources,
	)) {
		const candidate = provenance.candidates.find(
			(entry) => entry.id === candidateId,
		);
		assert(candidate, "required artifact candidate missing: " + candidateId);
		for (const sourcePath of requiredPaths)
			assert(
				candidate.sourcePaths.includes(sourcePath),
				candidateId + " source coverage is missing " + sourcePath,
			);
	}
	const requiredCandidates = new Set([
		"node-package",
		"cli-package",
		"worker-bundle",
		"docker-image",
	]);
	for (const candidate of requiredCandidates)
		assert(
			provenance.candidates.some((entry) => entry.id === candidate),
			"required artifact candidate missing: " + candidate,
		);
	for (const required of [
		"generated-client",
		"server-manifest",
		"plugin-manifest",
		"node-dist",
		"node-package-tarball",
		"cli-dist",
		"cli-package-tarball",
		"worker-dry-run",
		"docker-image-output",
	])
		assert(
			provenance.outputs.some((entry) => entry.id === required),
			"required artifact output missing: " + required,
		);
	return provenance;
}

function validateSelector(lane) {
	const selector = lane.selector;
	assert(
		selector && typeof selector === "object",
		lane.id + ".selector is required",
	);
	assert(
		selectorKinds.has(selector.kind),
		lane.id + " has unknown selector kind " + selector.kind,
	);
	for (const field of ["include", "exclude"]) {
		if (selector[field] === undefined) continue;
		assertArray(selector[field], lane.id + ".selector." + field);
		for (const path of selector[field])
			assertString(path, lane.id + ".selector path");
	}
	for (const field of ["config", "workspace", "project", "check"])
		if (selector[field] !== undefined)
			assertString(selector[field], lane.id + ".selector." + field);
}

export function validateAggregateAcyclicity(aggregates) {
	const visiting = new Set();
	const visited = new Set();
	const visit = (id, stack) => {
		if (visiting.has(id))
			throw new Error(
				"Validation aggregate cycle: " + [...stack, id].join(" -> "),
			);
		if (visited.has(id)) return;
		const aggregate = aggregates[id];
		if (!aggregate) return;
		visiting.add(id);
		for (const member of aggregate.lanes || [])
			if (aggregates[member]) visit(member, [...stack, id]);
		visiting.delete(id);
		visited.add(id);
	};
	for (const id of Object.keys(aggregates || {})) visit(id, []);
}

export function flattenAggregateLanes(aggregates, laneIds, aggregateId) {
	const flatten = (id, stack = []) => {
		assert(
			!stack.includes(id),
			"validation aggregate cycle: " + [...stack, id].join(" -> "),
		);
		const aggregate = aggregates[id];
		assert(aggregate, "validation aggregate " + id + " is required");
		return aggregate.lanes.flatMap((member) =>
			laneIds.has(member) ? [member] : flatten(member, [...stack, id]),
		);
	};
	return flatten(aggregateId);
}

export function validateValidationLanes(rootDir, lanes, topology, provenance) {
	assert(
		lanes && lanes.version === 1,
		"validation lane manifest version must be 1",
	);
	assert(
		lanes.runtimeMatrix && typeof lanes.runtimeMatrix === "object",
		"validation runtimeMatrix is required",
	);
	for (const [runtimeId, runtime] of Object.entries(lanes.runtimeMatrix)) {
		assertString(runtimeId, "validation runtime id");
		assert(
			runtime && typeof runtime === "object",
			runtimeId + " runtime is required",
		);
		assertString(runtime.kind, runtimeId + ".kind");
		assert(
			allowedRuntimes.has(runtime.kind),
			runtimeId + " has unknown runtime kind " + runtime.kind,
		);
		assertString(runtime.version, runtimeId + ".version");
	}
	assertArray(lanes.lanes, "validation lanes");
	assert(
		lanes.aggregates && typeof lanes.aggregates === "object",
		"validation aggregates are required",
	);
	assertArray(lanes.unresolvedMappings, "validation unresolvedMappings");
	assertUnique(
		lanes.lanes.map((lane) => lane.id),
		"validation lane ids",
	);
	const laneIds = new Set(lanes.lanes.map((lane) => lane.id));
	const project = JSON.parse(
		readFileSync(resolve(rootDir, "project.json"), "utf8"),
	);
	const projectTargets = new Set(Object.keys(project.targets || {}));
	const packageJson = JSON.parse(
		readFileSync(resolve(rootDir, "package.json"), "utf8"),
	);
	const targetInvokesPublication = (target) => {
		const config = project.targets?.[target] || {};
		const commands = [
			packageJson.scripts?.[target],
			config.options?.command,
			...(config.options?.commands || []),
			config.metadata?.scriptContent,
			config.metadata?.runCommand,
		].filter((command) => typeof command === "string");
		const hasPublicationCommand = commands.some((command) =>
			/(?:npm\s+publish|nx\s+release\s+publish|changeset\s+publish)/.test(
				command,
			),
		);
		if (hasPublicationCommand) return true;
		for (const command of commands) {
			const runMatch = /npm\s+run\s+(\S+)/.exec(command);
			if (runMatch && packageJson.scripts?.[runMatch[1]]) {
				if (
					/(?:npm\s+publish|nx\s+release\s+publish|changeset\s+publish)/.test(
						packageJson.scripts[runMatch[1]],
					)
				)
					return true;
			}
		}
		return false;
	};
	const aliases = new Set();
	for (const lane of lanes.lanes) {
		for (const field of [
			"id",
			"nxTarget",
			"mappingStatus",
			"selector",
			"runtimes",
			"credentials",
			"artifacts",
			"gate",
			"comparison",
		])
			assert(
				lane[field] !== undefined,
				"validation lane " + (lane.id || "?") + " needs " + field,
			);
		assertUnique([lane.id], "validation lane id");
		validateSelector(lane);
		assertArray(lane.runtimes, lane.id + ".runtimes");
		if (lane.workflowRuntimes !== undefined) {
			assertArray(lane.workflowRuntimes, lane.id + ".workflowRuntimes");
			for (const runtime of lane.workflowRuntimes)
				assert(
					lanes.runtimeMatrix[runtime],
					lane.id + " references unknown workflow runtime " + runtime,
				);
		}
		assertArray(lane.artifacts, lane.id + ".artifacts");
		assert(
			mappingStatuses.has(lane.mappingStatus),
			lane.id + " has unknown mappingStatus",
		);
		if (lane.mappingStatus === "mapped") {
			assertString(lane.nxTarget, lane.id + ".nxTarget");
			assert(
				projectTargets.has(lane.nxTarget),
				lane.id + " references missing Nx target " + lane.nxTarget,
			);
			assert(
				!targetInvokesPublication(lane.nxTarget),
				lane.id + " mapped target must not invoke changeset publish",
			);
		} else if (lane.mappingStatus === "external") {
			assert(
				lane.external === true,
				lane.id + " external mapping must be marked external",
			);
			assert(
				lane.nxTarget === null,
				lane.id + " external mapping must not invent an Nx target",
			);
			assertString(lane.integration, lane.id + ".integration");
		} else {
			assert(
				lane.nxTarget === null,
				lane.id + " unresolved mapping must be explicit",
			);
			assertString(lane.mappingReason, lane.id + ".mappingReason");
		}
		assert(
			!("command" in lane),
			lane.id + " must not encode dispatcher commands",
		);
		if (lane.alias !== undefined) {
			assertString(lane.alias, lane.id + ".alias");
			assert(
				!aliases.has(lane.alias),
				"validation lane alias duplicated: " + lane.alias,
			);
			assert(
				typeof packageJson.scripts[lane.alias] === "string",
				lane.id + " alias is not a root script",
			);
			assert(
				!packageJson.scripts[lane.alias].includes("run-validation-lane.mjs"),
				lane.id + " alias recurses through the dispatcher",
			);
			aliases.add(lane.alias);
		}
		for (const runtime of lane.runtimes)
			assert(
				lanes.runtimeMatrix[runtime],
				lane.id + " references unknown runtime " + runtime,
			);
		assertArray(lane.credentials, lane.id + ".credentials");
		assert(
			lane.credentials.every((credential) =>
				/^[A-Z][A-Z0-9_]+$/.test(credential),
			),
			lane.id + " credentials must be environment variable names",
		);
		assert(
			gateKinds.has(lane.gate),
			lane.id + " has unknown gate " + lane.gate,
		);
		assertString(lane.comparison, lane.id + ".comparison");
		for (const artifact of lane.artifacts) {
			const output = provenance.outputs.find((entry) => entry.id === artifact);
			const candidate = provenance.candidates.find(
				(entry) => entry.id === artifact,
			);
			assert(
				output || candidate,
				lane.id + " references unknown artifact " + artifact,
			);
			if (output)
				assert(
					output.owners.includes(lane.id),
					lane.id + " references output it does not own: " + artifact,
				);
			else
				assert(
					candidate.validation.includes(lane.id),
					lane.id + " references candidate it does not validate: " + artifact,
				);
		}
	}
	const laneById = new Map(lanes.lanes.map((lane) => [lane.id, lane]));
	for (const candidate of provenance.candidates) {
		const linkedArtifacts = new Set([candidate.id, ...candidate.outputs]);
		for (const laneId of candidate.validation) {
			const lane = laneById.get(laneId);
			assert(
				lane.artifacts.some((artifact) => linkedArtifacts.has(artifact)),
				candidate.id +
					" validation lane does not reference the candidate or an output: " +
					laneId,
			);
		}
	}
	const aggregates = lanes.aggregates;
	validateAggregateAcyclicity(aggregates);
	const unresolved = new Set(lanes.unresolvedMappings.map((entry) => entry.id));
	const laneStatuses = new Map(
		lanes.lanes.map((lane) => [lane.id, lane.mappingStatus]),
	);
	for (const lane of lanes.lanes)
		if (lane.mappingStatus === "unresolved") unresolved.add(lane.id);
	for (const [id, aggregate] of Object.entries(aggregates)) {
		assertArray(aggregate.lanes, "aggregate " + id + ".lanes");
		assert(
			mappingStatuses.has(aggregate.mappingStatus),
			id + " has unknown mappingStatus",
		);
		if (aggregate.mappingStatus === "mapped") {
			assertString(aggregate.nxTarget, id + ".nxTarget");
			assert(
				projectTargets.has(aggregate.nxTarget),
				id + " references missing Nx target " + aggregate.nxTarget,
			);
			assert(
				!targetInvokesPublication(aggregate.nxTarget),
				id + " mapped target must not invoke changeset publish",
			);
		} else if (aggregate.mappingStatus === "external") {
			assert(
				aggregate.external === true,
				id + " external mapping must be marked external",
			);
			assert(
				aggregate.nxTarget === null,
				id + " external mapping must not invent an Nx target",
			);
			assertString(aggregate.integration, id + ".integration");
			assert(
				!("mappingReason" in aggregate),
				id + " external mapping must not be unresolved",
			);
		} else {
			assert(
				aggregate.nxTarget === null,
				id + " non-mapped aggregate must not invent an Nx target",
			);
			assertString(aggregate.mappingReason, id + ".mappingReason");
			unresolved.add(id);
		}
		for (const member of aggregate.lanes)
			assert(
				laneIds.has(member) ||
					Object.prototype.hasOwnProperty.call(aggregates, member),
				id + " references unknown lane or aggregate " + member,
			);
	}
	for (const [id, aggregate] of Object.entries(aggregates)) {
		if (aggregate.workflowRuntimes === undefined) continue;
		assert(
			aggregate.workflowRuntimes &&
				typeof aggregate.workflowRuntimes === "object" &&
				!Array.isArray(aggregate.workflowRuntimes),
			id + ".workflowRuntimes must be an object",
		);
		const members = new Set(flattenAggregateLanes(aggregates, laneIds, id));
		for (const [laneId, runtimes] of Object.entries(
			aggregate.workflowRuntimes,
		)) {
			assert(
				members.has(laneId),
				id +
					".workflowRuntimes references a lane outside the aggregate: " +
					laneId,
			);
			assertArray(runtimes, id + ".workflowRuntimes." + laneId);
			assert(
				runtimes.length > 0 &&
					runtimes.every(
						(runtime) =>
							typeof runtime === "string" &&
							runtime.length > 0 &&
							lanes.runtimeMatrix[runtime],
					),
				id + ".workflowRuntimes." + laneId + " references an unknown runtime",
			);
		}
	}
	for (const entry of lanes.unresolvedMappings) {
		assertString(entry.id, "unresolved mapping id");
		assertString(entry.reason, entry.id + ".reason");
		assert(
			laneIds.has(entry.id) ||
				Object.prototype.hasOwnProperty.call(aggregates, entry.id),
			"unresolved mapping references unknown identity " + entry.id,
		);
	}
	assert(
		[...unresolved].every((id) =>
			lanes.unresolvedMappings.some((entry) => entry.id === id),
		),
		"every unresolved mapping needs an explicit decision record",
	);
	const containsUnresolvedMember = (id, stack = []) => {
		if (stack.includes(id)) return false;
		if (unresolved.has(id)) return true;
		const aggregate = aggregates[id];
		if (!aggregate) return laneStatuses.get(id) === "unresolved";
		if (aggregate.mappingStatus === "unresolved") return true;
		return aggregate.lanes.some((member) =>
			containsUnresolvedMember(member, [...stack, id]),
		);
	};
	for (const [id, aggregate] of Object.entries(aggregates))
		if (aggregate.mappingStatus === "external")
			assert(
				!containsUnresolvedMember(id),
				id + " external aggregate includes an unresolved member",
			);
	for (const [id, aggregate] of Object.entries(aggregates))
		if (aggregate.mappingStatus === "mapped")
			assert(
				!containsUnresolvedMember(id),
				id + " mapped aggregate includes an unresolved member",
			);
	const aggregateTargetMembers = (id) =>
		(aggregates[id]?.lanes ?? []).map((member) => {
			const lane = laneById.get(member);
			return lane?.nxTarget ?? aggregates[member]?.nxTarget;
		});
	const sortTargets = (values) =>
		[...new Set(values)].sort((left, right) => left.localeCompare(right));
	for (const [id, aggregate] of Object.entries(aggregates)) {
		if (aggregate.mappingStatus !== "mapped") continue;
		const target = project.targets[aggregate.nxTarget];
		const expected = aggregateTargetMembers(id);
		const actual = (target.dependsOn ?? []).map((dependency) =>
			typeof dependency === "string" ? dependency : dependency.target,
		);
		assert(
			actual.every((dependency) => typeof dependency === "string"),
			id + " mapped target dependencies must be target names",
		);
		assert(
			JSON.stringify(sortTargets(actual)) ===
				JSON.stringify(sortTargets(expected)),
			id +
				" Nx target dependsOn must match aggregate members; expected " +
				expected.join(", ") +
				" but found " +
				actual.join(", "),
		);
	}
	return lanes;
}

export function validateControlPlane(rootDir = repositoryRoot) {
	const controlPlane = loadControlPlane(rootDir);
	const artifactIds = new Set([
		...controlPlane.provenance.outputs.map((entry) => entry.id),
		...controlPlane.provenance.candidates.map((entry) => entry.id),
	]);
	validateTopology(rootDir, controlPlane.topology, artifactIds);
	validateArtifactProvenance(
		controlPlane.provenance,
		controlPlane.topology,
		new Set(controlPlane.lanes.lanes.map((lane) => lane.id)),
		rootDir,
	);
	validateValidationLanes(
		rootDir,
		controlPlane.lanes,
		controlPlane.topology,
		controlPlane.provenance,
	);
	return controlPlane;
}

