} from "./repository-control-plane.mjs";

export const validationLaneTableStart =
	"<!-- repository-control-plane:validation-lanes:start -->";
export const validationLaneTableEnd =
	"<!-- repository-control-plane:validation-lanes:end -->";
export const validationAggregateTableStart =
	"<!-- repository-control-plane:validation-aggregates:start -->";
export const validationAggregateTableEnd =
	"<!-- repository-control-plane:validation-aggregates:end -->";

const documentationFiles = ["CONTRIBUTING.md", "docs/test-lanes.md"];

function assert(condition, message) {
	if (!condition) throw new Error(message);
}

function renderList(values) {
	return values.length > 0 ? values.join(", ") : "—";
}

function renderPurpose(lane) {
	const selector = lane.selector;
	const details = [];

	if (selector.include?.length)
		details.push(`include: ${selector.include.join(", ")}`);
	if (selector.exclude?.length)
		details.push(`exclude: ${selector.exclude.join(", ")}`);
	if (selector.config) details.push(`config: ${selector.config}`);
	if (selector.workspace) details.push(`workspace: ${selector.workspace}`);
	if (selector.project) details.push(`project: ${selector.project}`);
	if (selector.check) details.push(`check: ${selector.check}`);
	return [selector.kind, ...details].join("; ");
}

function validateLane(lane, index) {
	assert(
		lane && typeof lane === "object",
		`validation lane ${index} is required`,
	);
	assert(
		typeof lane.id === "string" && lane.id.length > 0,
		`validation lane ${index} needs an id`,
	);
	assert(
		!Object.prototype.hasOwnProperty.call(lane, "command"),
		`${lane.id} must not encode dispatcher commands`,
	);
	assert(
		lane.selector && typeof lane.selector === "object",
		`${lane.id} selector is required`,
	);
	assert(
		typeof lane.gate === "string" && lane.gate.length > 0,
		`${lane.id} gate is required`,
	);
	assert(Array.isArray(lane.runtimes), `${lane.id}.runtimes must be an array`);
	assert(
		Array.isArray(lane.credentials),
		`${lane.id}.credentials must be an array`,
	);
	assert(
		Array.isArray(lane.artifacts),
		`${lane.id}.artifacts must be an array`,
	);
	assert(
		typeof lane.mappingStatus === "string",
		`${lane.id}.mappingStatus is required`,
	);
	if (lane.external === true) {
		assert(
			typeof lane.integration === "string" && lane.integration.length > 0,
			`${lane.id} external lanes need integration ownership`,
		);
		assert(
			lane.alias === undefined,
			`${lane.id} external lanes must not advertise an alias`,
		);
		assert(
			lane.nxTarget === null,
			`${lane.id} external lanes must not advertise an Nx target`,
		);
		return;
	}
	if (lane.alias !== undefined)
		assert(
			typeof lane.alias === "string" && lane.alias.length > 0,
			`${lane.id} alias must be a non-empty string`,
		);
	if (lane.mappingStatus === "mapped")
		assert(
			typeof lane.nxTarget === "string" && lane.nxTarget.length > 0,
			`${lane.id} mapped lanes need an Nx target`,
		);
	else
		assert(
			lane.nxTarget === null,
			`${lane.id} non-mapped lanes must not advertise an Nx target`,
		);
}

function validateManifest(manifest) {
	assert(
		manifest && typeof manifest === "object",
		"validation lanes are required",
	);
	assert(Array.isArray(manifest.lanes), "validation lanes must be an array");
	assert(
		manifest.aggregates && typeof manifest.aggregates === "object",
		"validation aggregates are required",
	);
	const laneIds = new Set();
	for (const [index, lane] of manifest.lanes.entries()) {
		validateLane(lane, index);
		assert(!laneIds.has(lane.id), `validation lane id duplicated: ${lane.id}`);
		laneIds.add(lane.id);
	}
	const aggregateIds = new Set(Object.keys(manifest.aggregates));
	for (const [id, aggregate] of Object.entries(manifest.aggregates)) {
		assert(
			aggregate && typeof aggregate === "object",
			`${id} aggregate is required`,
		);
		assertArray(aggregate.lanes, `aggregate ${id}.lanes`);
		assert(
			typeof aggregate.mappingStatus === "string",
			`${id}.mappingStatus is required`,
		);
		for (const member of aggregate.lanes)
			assert(
				laneIds.has(member) || aggregateIds.has(member),
				`${id} references unknown lane or aggregate ${member}`,
			);
		if (aggregate.external === true) {
			assert(
				aggregate.mappingStatus === "external",
				`${id} external aggregates must use external mapping`,
			);
			assert(
				typeof aggregate.integration === "string" &&
					aggregate.integration.length > 0,
				`${id} external aggregates need integration ownership`,
			);
			assert(
				aggregate.alias === undefined,
				`${id} external aggregates must not advertise an alias`,
			);
		} else if (aggregate.mappingStatus === "mapped")
			assert(
				typeof aggregate.nxTarget === "string" && aggregate.nxTarget.length > 0,
				`${id} mapped aggregates need an Nx target`,
			);
		else
			assert(
				aggregate.nxTarget === null,
				`${id} non-mapped aggregates must not advertise an Nx target`,
			);
	}
	validateAggregateAcyclicity(manifest.aggregates);
	return manifest;
}

function assertArray(value, label) {
	assert(Array.isArray(value), `${label} must be an array`);
}

function validateAggregateAcyclicity(aggregates) {
	const visiting = new Set();
	const visited = new Set();
	const visit = (id, stack) => {
		if (visiting.has(id))
			throw new Error(
				`Validation aggregate cycle: ${[...stack, id].join(" -> ")}`,
			);
		if (visited.has(id)) return;
		const aggregate = aggregates[id];
		if (!aggregate) return;
		visiting.add(id);
		for (const member of aggregate.lanes) {
			if (aggregates[member]) visit(member, [...stack, id]);
		}
		visiting.delete(id);
		visited.add(id);
	};
	for (const id of Object.keys(aggregates)) visit(id, []);
}

function renderMarkdownTable(rows) {
	const widths = rows[0].map((_, index) =>
		Math.max(...rows.map((row) => row[index].length), 3),
	);
	const renderRow = (row) =>
		`| ${row.map((cell, index) => cell.padEnd(widths[index])).join(" | ")} |`;
	const separator = `| ${widths.map((width) => "-".repeat(width)).join(" | ")} |`;
	return [renderRow(rows[0]), separator, ...rows.slice(1).map(renderRow)].join(
		"\n",
	);
}

function renderNxTarget(target) {
	return target ? `npx nx run repository:${target}` : "—";
}

function renderLaneCommand(lane) {
	if (lane.external === true) return `external: ${lane.integration}`;
	const command = lane.alias
		? `npm run ${lane.alias}`
		: renderNxTarget(lane.nxTarget);
	assert(command !== "—", `${lane.id} has no contributor command or Nx target`);
	return lane.alias && lane.nxTarget
		? `${command} (Nx: repository:${lane.nxTarget})`
		: command;
}

function renderAggregateCommand(aggregate, id) {
	if (aggregate.external === true) {
		assert(
			typeof aggregate.integration === "string" &&
				aggregate.integration.length > 0,
			`${id} external aggregates need integration ownership`,
		);
		return `external: ${aggregate.integration}`;
	}
	if (aggregate.alias !== undefined) {
		assert(
			typeof aggregate.alias === "string" && aggregate.alias.length > 0,
			`${id} alias must be a non-empty string`,
		);
		return aggregate.nxTarget
			? `npm run ${aggregate.alias} (Nx: repository:${aggregate.nxTarget})`
			: `npm run ${aggregate.alias}`;
	}
	return renderNxTarget(aggregate.nxTarget);
}

function renderLaneTableBody(manifest) {
	const rows = [
		[
			"Lane ID",
			"Command / integration",
			"Gate",
			"Runtime ownership",
			"Credentials",
			"Artifacts",
			"Purpose",
		],
	];
	for (const lane of manifest.lanes) {
		rows.push([
			`\`${lane.id}\``,
			renderLaneCommand(lane),
			lane.gate,
			renderList(lane.runtimes),
			renderList(lane.credentials),
			renderList(lane.artifacts),
			renderPurpose(lane),
		]);
	}
	return renderMarkdownTable(rows);
}

export function renderValidationAggregateTable(
	manifest = loadValidationLanes(),
) {
	validateManifest(manifest);
	const rows = [
		["Aggregate ID", "Nx target / command", "Members", "Count", "Mapping"],
	];
	for (const [id, aggregate] of Object.entries(manifest.aggregates)) {
		rows.push([
			`\`${id}\``,
			renderAggregateCommand(aggregate, id),
			aggregate.lanes.map((member) => `\`${member}\``).join(", ") || "—",
			String(aggregate.lanes.length),
			aggregate.mappingStatus,
		]);
	}
	return [
		validationAggregateTableStart,
		"",
		renderMarkdownTable(rows),
		"",
		validationAggregateTableEnd,
	].join("\n");
}

export function renderValidationLaneTable(manifest = loadValidationLanes()) {
	validateManifest(manifest);
	return [
		validationLaneTableStart,
		"",
		renderLaneTableBody(manifest),
		"",
		renderValidationAggregateTable(manifest),
		"",
		validationLaneTableEnd,
	].join("\n");
}

function replaceMarkedTable(contents, startMarker, endMarker, table, label) {
	const starts = [
		...contents.matchAll(new RegExp(escapeRegExp(startMarker), "g")),
	];
	const ends = [...contents.matchAll(new RegExp(escapeRegExp(endMarker), "g"))];
	if (
		starts.length === 0 ||
		ends.length === 0 ||
		starts[0].index > ends[0].index
	)
		throw new Error(`${label} markers are missing or out of order`);
	if (starts.length !== 1 || ends.length !== 1)
		throw new Error(`${label} markers are duplicated`);
	const endOffset = ends[0].index + endMarker.length;
	return `${contents.slice(0, starts[0].index)}${table}${contents.slice(endOffset)}`;
}

function escapeRegExp(value) {
	return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function replaceValidationLaneTable(contents, table) {
	return replaceMarkedTable(
		contents,
		validationLaneTableStart,
		validationLaneTableEnd,
		table,
		"Validation lane table",
	);
}

export function replaceValidationAggregateTable(contents, table) {
	return replaceMarkedTable(
		contents,
		validationAggregateTableStart,
		validationAggregateTableEnd,
		table,
		"Validation aggregate table",
	);
}

export async function checkRenderedValidationLaneTables(
	rootDir = repositoryRoot,
) {
	const manifest = validateManifest(loadValidationLanes(rootDir));
	const table = renderValidationLaneTable(manifest);
	for (const file of documentationFiles) {
		const path = resolve(rootDir, file);
		const contents = await readFile(path, "utf8");
		const actual = replaceValidationLaneTable(contents, table);
		if (actual !== contents)
			throw new Error(`${file} validation lane table is stale; regenerate it`);
	}
}

export async function renderValidationLaneTables(rootDir = repositoryRoot) {
	const manifest = validateManifest(loadValidationLanes(rootDir));
	const table = renderValidationLaneTable(manifest);
	for (const file of documentationFiles) {
		const path = resolve(rootDir, file);
		const contents = await readFile(path, "utf8");
		await writeFile(path, replaceValidationLaneTable(contents, table));
	}
}

export function isDirectInvocation(argvPath = process.argv[1]) {
	return Boolean(
		argvPath && resolve(argvPath) === fileURLToPath(import.meta.url),
	);
}

if (isDirectInvocation()) {
	try {
		if (process.argv.includes("--write")) await renderValidationLaneTables();
		else await checkRenderedValidationLaneTables();
	} catch (error) {
		console.error(`render-validation-lanes: ${error.message}`);
		process.exitCode = 1;
	}
}

import { existsSync } from "node:fs";
import { access, readFile, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import {
	loadArtifactProvenance,
	repositoryRoot,
} from "./repository-control-plane.mjs";

const manifestSchema =
	"https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json";
const repositoryUrl = "https://github.com/chrisdoc/hevy-mcp";

function assert(condition, message) {
	if (!condition) {
		throw new Error(message);
	}
}

async function readJson(path, label) {
	let contents;
	try {
		contents = await readFile(path, "utf8");
	} catch (error) {
		const readError = new Error(`Unable to read ${label}: ${error.message}`);
		readError.cause = error;
		throw readError;
	}

	try {
		return { contents, value: JSON.parse(contents) };
	} catch (error) {
		throw new Error(`${label} is not valid JSON: ${error.message}`);
	}
}

function loadManifestProvenance(rootDir) {
	const fixtureProvenance = resolve(
		rootDir,
		"repository",
		"artifact-provenance.json",
	);
	return existsSync(fixtureProvenance)
		? loadArtifactProvenance(rootDir)
		: loadArtifactProvenance(repositoryRoot);
}

function provenanceEntry(provenance, collection, id, pathCount) {
	const entries = provenance?.[collection];
	assert(
		Array.isArray(entries),
		`Artifact provenance ${collection} entries are required`,
	);
	const matches = entries.filter((candidate) => candidate?.id === id);
	assert(
		matches.length === 1,
		`Artifact provenance ${collection} entry ${id} must be unique`,
	);
	const [entry] = matches;
	assert(
		Array.isArray(entry.paths) && entry.paths.length > 0,
		`Artifact provenance ${collection} entry ${id} paths are required`,
	);
	if (pathCount !== undefined)
		assert(
			entry.paths.length === pathCount,
			`Artifact provenance ${collection} entry ${id} must own exactly ${pathCount} path${pathCount === 1 ? "" : "s"}`,
		);
	assert(
		entry.paths.every((path) => typeof path === "string" && path.length > 0),
		`Artifact provenance ${collection} entry ${id} paths must be non-empty`,
	);
	assert(
		new Set(entry.paths).size === entry.paths.length,
		`Artifact provenance ${collection} entry ${id} paths must be unique`,
	);
	return entry;
}

function resolveProvenancePaths(
	rootDir,
	provenance,
	collection,
	id,
	pathCount,
) {
	return provenanceEntry(provenance, collection, id, pathCount).paths.map(
		(path) => ({
			path: resolve(rootDir, path),
			relativePath: path,
		}),
	);
}

async function resolvePackageMetadata(rootDir, provenance) {
	const [nodePackageSource] = resolveProvenancePaths(
		rootDir,
		provenance,
		"sources",
		"node-package-manifest",
		1,
	);
	try {
		await access(nodePackageSource.path);
		return {
			packagePath: nodePackageSource.path,
			packageLabel: nodePackageSource.relativePath,
		};
	} catch {
		return {
			packagePath: resolve(rootDir, "package.json"),
			packageLabel: "package.json",
		};
	}
}

function validatePackageJson(packageJson) {
	assert(
		packageJson?.name === "hevy-mcp",
		"package.json name must be hevy-mcp",
	);
	assert(
		packageJson.mcpName === "io.github.chrisdoc/hevy-mcp",
		"package.json mcpName must be io.github.chrisdoc/hevy-mcp",
	);
	assert(
		typeof packageJson.version === "string" && packageJson.version.length > 0,
		"package.json version must be a non-empty string",
	);
	assert(
		Array.isArray(packageJson.files) &&
			packageJson.files.includes("server.json"),
		"package.json files must include server.json",
	);
}

function validateManifestShape(manifest) {
	assert(
		manifest && typeof manifest === "object" && !Array.isArray(manifest),
		"server.json must contain an object",
	);
	assert(
		manifest.$schema === manifestSchema,
		"server.json has an unexpected $schema",
	);
	assert(
		manifest.title === "Hevy MCP Server",
		"server.json has an unexpected title",
	);
	assert(
		manifest.description ===
			"MCP server for managing workouts, routines, and exercise data through the Hevy API",
		"server.json has an unexpected description",
	);
	assert(
		manifest.repository?.url === repositoryUrl &&
			manifest.repository?.source === "github",
		"server.json has unexpected repository metadata",
	);
	assert(
		Array.isArray(manifest.packages) && manifest.packages.length === 1,
		"server.json must contain exactly one package",
	);

	const [packageEntry] = manifest.packages;
	assert(
		packageEntry.registryType === "npm",
		"server.json package registryType must be npm",
	);
	assert(
		packageEntry.transport?.type === "stdio",
		"server.json package transport must be stdio",
	);
	assert(
		Array.isArray(packageEntry.environmentVariables) &&
			packageEntry.environmentVariables.length === 1,
		"server.json package must declare exactly one environment variable",
	);

	const [apiKey] = packageEntry.environmentVariables;
	assert(
		apiKey.name === "HEVY_API_KEY" &&
			apiKey.description === "API key for authenticating with the Hevy API" &&
			apiKey.isRequired === true &&
			apiKey.isSecret === true,
		"server.json has unexpected HEVY_API_KEY metadata",
	);
}

function findDrift(packageJson, manifest) {
	const packageEntry = manifest.packages[0];
	const drift = [];

	if (manifest.name !== packageJson.mcpName) {
		drift.push("name");
	}
	if (manifest.version !== packageJson.version) {
		drift.push("version");
	}
	if (packageEntry.identifier !== packageJson.name) {
		drift.push("packages[0].identifier");
	}
	if (packageEntry.version !== packageJson.version) {
		drift.push("packages[0].version");
	}

	return drift;
}

export async function runServerManifest({ mode, rootDir = process.cwd() }) {
	assert(
		mode === "check" || mode === "sync",
		`Invalid mode ${JSON.stringify(mode)}; expected "check" or "sync"`,
	);

	const provenance = loadManifestProvenance(rootDir);
	const { packagePath, packageLabel } = await resolvePackageMetadata(
		rootDir,
		provenance,
	);
	const serverManifestPaths = resolveProvenancePaths(
		rootDir,
		provenance,
		"outputs",
		"server-manifest",
	);
	const pluginManifestPaths = resolveProvenancePaths(
		rootDir,
		provenance,
		"outputs",
		"plugin-manifest",
	);
	const [primaryManifest, ...mirrorManifests] = serverManifestPaths;
	const manifestPath = primaryManifest.path;
	const [{ value: packageJson }, { value: manifest }] = await Promise.all([
		readJson(packagePath, packageLabel),
		readJson(manifestPath, primaryManifest.relativePath),
	]);
	const packageManifests = [];
	for (const mirror of mirrorManifests) {
		try {
			packageManifests.push({
				...mirror,
				value: (await readJson(mirror.path, mirror.relativePath)).value,
			});
		} catch (error) {
			if (error.cause?.code !== "ENOENT") throw error;
		}
	}
	const pluginManifests = [];
	for (const plugin of pluginManifestPaths) {
		try {
			pluginManifests.push({
				...plugin,
				value: (await readJson(plugin.path, plugin.relativePath)).value,
			});
		} catch (error) {
			if (error.cause?.code !== "ENOENT") throw error;
		}
	}

	validatePackageJson(packageJson);
	validateManifestShape(manifest);

	const drift = findDrift(packageJson, manifest);
	for (const packageManifest of packageManifests) {
		if (JSON.stringify(packageManifest.value) !== JSON.stringify(manifest))
			drift.push(packageManifest.relativePath);
	}
	for (const plugin of pluginManifests)
		if (plugin.value.version !== packageJson.version)
			drift.push(plugin.relativePath);
	if (mode === "check") {
		assert(
			drift.length === 0,
			`server.json or plugin.json is out of sync with package.json: ${drift.join(", ")}. Run npm run sync:server-manifest.`,
		);
		return { changed: false, drift };
	}

	if (drift.length === 0) {
		return { changed: false, drift };
	}

	manifest.name = packageJson.mcpName;
	manifest.version = packageJson.version;
	manifest.packages[0].identifier = packageJson.name;
	manifest.packages[0].version = packageJson.version;

	const updatedContents = `${JSON.stringify(manifest, null, "\t")}\n`;
	await writeFile(manifestPath, updatedContents, "utf8");
	for (const mirror of mirrorManifests) {
		try {
			await access(dirname(mirror.path));
		} catch (error) {
			if (error.code === "ENOENT") {
				// Fixture repositories may only include the primary manifest output.
				continue;
			}
			throw error;
		}
		await writeFile(mirror.path, updatedContents, "utf8");
	}

	for (const plugin of pluginManifests) {
		if (plugin.value.version === packageJson.version) continue;
		plugin.value.version = packageJson.version;
		const updatedPluginContents = `${JSON.stringify(plugin.value, null, "\t")}\n`;
		await writeFile(plugin.path, updatedPluginContents, "utf8");
	}

	return { changed: true, drift };
}

const isCli =
	process.argv[1] !== undefined &&
	import.meta.url === pathToFileURL(resolve(process.argv[1])).href;

if (isCli) {
	try {
		const result = await runServerManifest({ mode: process.argv[2] });
		console.log(
			result.changed
				? "Synchronized server.json and plugin.json with package.json."
				: "server.json and plugin.json are synchronized with package.json.",
		);
	} catch (error) {
		console.error(`server-manifest: ${error.message}`);
		process.exitCode = 1;
	}
}

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { load as parseYaml } from "js-yaml";

function assert(condition, message) {
	if (!condition) throw new Error(message);
}

function normalizeCondition(condition) {
	if (condition === undefined || condition === null) return null;
	return String(condition).replace(/\s+/g, " ").trim();
}

function matrixValues(job) {
	const values = job?.strategy?.matrix?.["node-version"];
	return Array.isArray(values) ? values.map(String) : [];
}

function runtimeForMatrixValue(value) {
	const match = /^([0-9]+)(?:\.x)?$/.exec(value);
	if (!match) throw new Error(`Unsupported Node matrix value ${value}`);
	return `node-${match[1]}`;
}

function runtimeForVersionSpec(value, source) {
	const normalized = String(value).trim().replace(/^v/, "");
	const match = /^(\d+)(?:\.\d+){0,2}(?:\.x)?$/.exec(normalized);
	if (!match)
		throw new Error(`Unsupported Node version ${normalized} in ${source}`);
	return `node-${match[1]}`;
}

function setupNodeRuntimeByMatrix(step, rootDir, versions) {
	assert(
		normalizeCondition(step.if) === null,
		"actions/setup-node must be unconditional before validation lanes",
	);
	const options = step.with;
	assert(
		options && typeof options === "object",
		"actions/setup-node must declare with.node-version or node-version-file",
	);
	const nodeVersion = options["node-version"];
	const nodeVersionFile = options["node-version-file"];
	assert(
		!(nodeVersion !== undefined && nodeVersionFile !== undefined),
		"actions/setup-node must not declare both node-version and node-version-file",
	);

	let configuration;
	if (typeof nodeVersion === "string" || typeof nodeVersion === "number") {
		const value = String(nodeVersion).trim();
		if (value.includes("matrix.node-version")) {
			assert(
				versions.length > 0,
				"actions/setup-node matrix node-version requires a job matrix",
			);
			configuration = { kind: "matrix" };
		} else {
			configuration = {
				kind: "fixed",
				runtime: runtimeForVersionSpec(value, "setup-node node-version"),
			};
		}
	}
	if (typeof nodeVersionFile === "string") {
		const path = resolve(rootDir, nodeVersionFile);
		let version;
		try {
			version = readFileSync(path, "utf8")
				.split(/\r?\n/)
				.map((line) => line.trim())
				.find(Boolean);
		} catch (error) {
			throw new Error(
				`actions/setup-node node-version-file ${nodeVersionFile} is unavailable: ${error.message}`,
			);
		}
		assert(
			version,
			`actions/setup-node node-version-file ${nodeVersionFile} is empty`,
		);
		configuration = {
			kind: "fixed",
			runtime: runtimeForVersionSpec(
				version,
				`setup-node node-version-file ${nodeVersionFile}`,
			),
		};
	}
	assert(
		configuration,
		"actions/setup-node must declare node-version or node-version-file",
	);
	if (configuration.kind === "matrix")
		return new Map(
			versions.map((value) => [value, runtimeForMatrixValue(value)]),
		);
	if (versions.length === 0)
		return new Map([[undefined, configuration.runtime]]);
	return new Map(versions.map((value) => [value, configuration.runtime]));
}

function matrixValuesForCondition(condition, versions) {
	if (versions.length === 0) {
		assert(
			!condition?.includes("matrix.node-version"),
			`Workflow condition references a Node matrix for a non-matrix job: ${condition}`,
		);
		return [undefined];
	}
	if (!condition || !condition.includes("matrix.node-version")) return versions;
	if (/matrix\.node-version\s*!==?/.test(condition))
		throw new Error(
			`Workflow condition must use exact Node equality: ${condition}`,
		);
	const matches = [
		...condition.matchAll(/matrix\.node-version\s*==\s*['"]([^'"]+)['"]/g),
	];
	assert(
		matches.length === 1,
		`Workflow condition must select exactly one Node matrix value: ${condition}`,
	);
	const value = matches[0][1];
	assert(
		versions.includes(value),
		`Workflow condition selects an unknown Node matrix value ${value}`,
	);
	return [value];
}

function effectiveCondition(jobCondition, stepCondition) {
	if (jobCondition && stepCondition)
		return `${jobCondition} && (${stepCondition})`;
	return jobCondition ?? stepCondition;
}

function walkJobSteps(value, visit, path = []) {
	if (Array.isArray(value)) {
		for (const [index, item] of value.entries())
			walkJobSteps(item, visit, [...path, index]);
		return;
	}
	if (!value || typeof value !== "object") return;
	if (typeof value.run === "string" || typeof value.uses === "string") {
		visit(value, path);
		return;
	}
	for (const [key, child] of Object.entries(value))
		walkJobSteps(child, visit, [...path, key]);
}

function optionValue(tokens, longName, shortName) {
	for (let index = 0; index < tokens.length; index += 1) {
		const token = tokens[index];
		if (token.startsWith(`${longName}=`))
			return token.slice(longName.length + 1);
		if (token === longName || token === shortName)
			return tokens[index + 1] ?? "";
	}
	return null;
}

function parseNxRunCommands(line) {
	const normalized = line.trim().replace(/\s+/g, " ");
	const direct =
		/^npx nx run repository:([A-Za-z0-9][A-Za-z0-9:_-]*)(?: (.*?))?$/.exec(
			normalized,
		);
	if (direct) {
		const args = direct[2] ?? "";
		return [
			{
				target: direct[1],
				args,
				command: `npx nx run repository:${direct[1]}${args ? ` ${args}` : ""}`,
			},
		];
	}

	const aggregate = /^npx nx run-many(?: (.*?))?$/.exec(normalized);
	if (!aggregate) return [];
	const args = aggregate[1] ?? "";
	const tokens = args ? args.split(" ") : [];
	const targetList = optionValue(tokens, "--targets", "-t");
	if (targetList === null) return [];
	const projectList = optionValue(tokens, "--projects", "-p");
	assert(
		projectList === "repository",
		"Nx run-many must target only the repository project for workflow projection",
	);
	const targets = targetList.split(",").filter(Boolean);
	assert(targets.length > 0, "Nx run-many must declare at least one target");
	assert(
		new Set(targets).size === targets.length,
		"Nx run-many must not repeat targets",
	);
	return targets.map((target) => ({
		target,
		args,
		command: `npx nx run-many ${args}`,
	}));
}

function normalizeLaneTargets(laneTargets) {
	if (!laneTargets) return new Map();
	if (laneTargets instanceof Map) return new Map(laneTargets);
	const entries = Object.entries(laneTargets);
	return new Map(entries);
}

/**
 * Build the only target-to-lane mapping that workflow projection may use.
 * External and unresolved lanes are deliberately excluded and cannot invent
 * an Nx target.
 */
export function mappedLaneTargets(lanes) {
	assert(lanes && Array.isArray(lanes.lanes), "validation lanes are required");
	const targets = new Map();
	for (const lane of lanes.lanes) {
		assert(
			typeof lane.id === "string" && lane.id.length > 0,
			"validation lane id is required",
		);
		if (lane.mappingStatus === "mapped") {
			assert(
				typeof lane.nxTarget === "string" && lane.nxTarget.length > 0,
				`${lane.id} mapped lane requires nxTarget`,
			);
			assert(
				!targets.has(lane.nxTarget),
				`Nx target ${lane.nxTarget} is mapped more than once`,
			);
			targets.set(lane.nxTarget, lane.id);
			continue;
		}
		assert(
			lane.nxTarget === null,
			`${lane.id} ${lane.mappingStatus ?? "unknown"} lane must not invent an Nx target`,
		);
		assert(
			lane.mappingStatus === "external" || lane.mappingStatus === "unresolved",
			`${lane.id} has unknown mapping status ${lane.mappingStatus}`,
		);
	}
	return targets;
}

/**
 * Parse mapped `nx run` and repository-scoped `nx run-many` executions from a
 * workflow.
 * The returned entries retain the historical projection shape by default;
 * `includeCommands` adds the exact command identity for strict validation.
 */
export function parseWorkflowLaneExecutions(
	source,
	{
		rootDir = process.cwd(),
		laneTargets,
		includeCommands = false,
		jobIds,
	} = {},
) {
	const workflow = parseYaml(source);
	assert(
		workflow && typeof workflow === "object",
		"workflow must contain a YAML object",
	);
	const mappedTargets = normalizeLaneTargets(laneTargets);
	const selectedJobs = jobIds === undefined ? null : new Set(jobIds);
	if (selectedJobs) {
		assert(
			selectedJobs.size > 0 &&
				[...selectedJobs].every((id) => typeof id === "string"),
			"workflow jobIds must be a non-empty string array",
		);
	}
	const executions = [];
	for (const [jobId, job] of Object.entries(workflow.jobs ?? {})) {
		if (selectedJobs && !selectedJobs.has(jobId)) continue;
		const versions = matrixValues(job);
		const jobCondition = normalizeCondition(job.if);
		const steps = job.steps ?? [];
		let hasMappedCommand = false;
		walkJobSteps(steps, (step) => {
			if (typeof step.run !== "string") return;
			for (const line of step.run.split(/\r?\n/)) {
				for (const command of parseNxRunCommands(line)) {
					if (mappedTargets.has(command.target)) hasMappedCommand = true;
				}
			}
		});
		if (!hasMappedCommand) continue;

		const runtimeState = {
			byMatrixValue: null,
			setupNodeSeen: false,
		};
		walkJobSteps(steps, (step) => {
			if (
				typeof step.uses === "string" &&
				step.uses.startsWith("actions/setup-node@")
			) {
				assert(
					!runtimeState.setupNodeSeen,
					`Workflow job ${jobId} has multiple setup-node steps`,
				);
				runtimeState.byMatrixValue = setupNodeRuntimeByMatrix(
					step,
					rootDir,
					versions,
				);
				runtimeState.setupNodeSeen = true;
				return;
			}
			if (typeof step.run !== "string") return;
			for (const line of step.run.split(/\r?\n/)) {
				for (const command of parseNxRunCommands(line)) {
					if (!mappedTargets.has(command.target)) continue;
					assert(
						runtimeState.byMatrixValue,
						`Workflow lane ${mappedTargets.get(command.target)} must follow an unconditional setup-node step in job ${jobId}`,
					);
					const rawStepCondition = step.if ?? null;
					const stepCondition = normalizeCondition(rawStepCondition);
					const selectedByJob = matrixValuesForCondition(
						jobCondition,
						versions,
					);
					const selectedByStep = matrixValuesForCondition(
						stepCondition,
						versions,
					);
					const selectedValues = versions.length
						? versions.filter(
								(value) =>
									selectedByJob.includes(value) &&
									selectedByStep.includes(value),
							)
						: [undefined];
					const runtimes = [
						...new Set(
							selectedValues.map((value) =>
								runtimeState.byMatrixValue.get(value),
							),
						),
					];
					assert(
						runtimes.length > 0 && runtimes.every(Boolean),
						`Workflow lane ${mappedTargets.get(command.target)} has no runtime projection`,
					);
					const entry = {
						lane: mappedTargets.get(command.target),
						job: jobId,
						runtimes,
						condition: effectiveCondition(jobCondition, stepCondition),
						jobCondition,
						stepCondition,
					};
					if (includeCommands) {
						entry.target = command.target;
						entry.args = command.args;
						entry.command = command.command;
						entry.step = step.name ?? null;
					}
					executions.push(entry);
				}
			}
		});
	}
	return executions;
}

function aggregateLaneIds(lanes, aggregate) {
	assert(
		aggregate && Array.isArray(aggregate.lanes),
		"workflow aggregate lanes are required",
	);
	const laneIds = [];
	const laneById = new Map((lanes.lanes ?? []).map((lane) => [lane.id, lane]));
	const aggregates = lanes.aggregates ?? {};
	const visit = (id, stack) => {
		if (laneById.has(id)) {
			laneIds.push(id);
			return;
		}
		const nested = aggregates[id];
		assert(
			nested,
			`workflow aggregate references unknown lane or aggregate ${id}`,
		);
		assert(
			!stack.includes(id),
			`workflow aggregate cycle: ${[...stack, id].join(" -> ")}`,
		);
		assertArray(nested.lanes, `workflow aggregate ${id}.lanes`);
		for (const member of nested.lanes) visit(member, [...stack, id]);
	};
	for (const id of aggregate.lanes) visit(id, []);
	assert(
		new Set(laneIds).size === laneIds.length,
		"workflow aggregate contains duplicate lane membership",
	);
	return laneIds;
}

function assertArray(value, label) {
	assert(Array.isArray(value), `${label} must be an array`);
}

function sorted(values) {
	return [...values].sort((left, right) => left.localeCompare(right));
}

/**
 * Validate workflow executions against aggregate membership and each lane's
 * declared runtime set. Conditions remain observable in parsed output, but
 * are intentionally not copied into the canonical model.
 */
export function validateWorkflowAggregate(
	source,
	{
		lanes,
		aggregate,
		aggregateId,
		rootDir = process.cwd(),
		label = "workflow aggregate",
		expectedJobs,
		job,
		jobIds,
	} = {},
) {
	assert(
		lanes && Array.isArray(lanes.lanes),
		"canonical lane model is required",
	);
	const selectedAggregate =
		typeof aggregate === "string"
			? lanes.aggregates?.[aggregate]
			: (aggregate ?? lanes.aggregates?.[aggregateId]);
	assert(
		selectedAggregate && typeof selectedAggregate === "object",
		`${label} definition is required`,
	);
	const memberIds = aggregateLaneIds(lanes, selectedAggregate);
	const aggregateWorkflowRuntimes = selectedAggregate.workflowRuntimes;
	if (aggregateWorkflowRuntimes !== undefined) {
		assert(
			aggregateWorkflowRuntimes &&
				typeof aggregateWorkflowRuntimes === "object" &&
				!Array.isArray(aggregateWorkflowRuntimes),
			`${label}.workflowRuntimes must be an object`,
		);
		for (const [laneId, runtimes] of Object.entries(
			aggregateWorkflowRuntimes,
		)) {
			assert(
				memberIds.includes(laneId),
				`${label}.workflowRuntimes references a lane outside the aggregate: ${laneId}`,
			);
			assertArray(runtimes, `${label}.workflowRuntimes.${laneId}`);
			assert(
				runtimes.length > 0 &&
					runtimes.every(
						(runtime) => typeof runtime === "string" && runtime.length > 0,
					),
				`${label}.workflowRuntimes.${laneId} must contain runtime ids`,
			);
		}
	}
	const laneById = new Map((lanes.lanes ?? []).map((lane) => [lane.id, lane]));
	const targets = mappedLaneTargets(lanes);
	for (const laneId of memberIds) {
		const lane = laneById.get(laneId);
		assert(lane, `${label} references unknown lane ${laneId}`);
		assert(
			lane.mappingStatus === "mapped" && targets.has(lane.nxTarget),
			`${label} member ${laneId} is not mapped to Nx`,
		);
		assertArray(lane.runtimes, `${laneId}.runtimes`);
	}

	const actual = parseWorkflowLaneExecutions(source, {
		rootDir,
		laneTargets: targets,
		includeCommands: true,
		jobIds,
	});
	const expectedMembers = new Set(memberIds);
	const actualRuntimes = new Map();
	const executionIdentities = new Set();
	const expectedJobSelection = expectedJobs ?? job;
	for (const execution of actual) {
		if (expectedJobSelection !== undefined) {
			const expectedJob =
				typeof expectedJobSelection === "string"
					? expectedJobSelection
					: expectedJobSelection?.[execution.lane];
			assert(
				typeof expectedJob === "string" && expectedJob.length > 0,
				`${label} expected job is required for lane ${execution.lane}`,
			);
			assert(
				execution.job === expectedJob,
				`${label} job identity drifted for lane ${execution.lane}: expected ${expectedJob}, found ${execution.job}`,
			);
		}
		const identityPrefix = `${execution.lane}|${execution.target}|${execution.job}`;
		for (const runtime of execution.runtimes) {
			const identity = `${identityPrefix}|${runtime}`;
			assert(
				!executionIdentities.has(identity),
				`${label} contains duplicate mapped command identity ${identity}`,
			);
			executionIdentities.add(identity);
			const runtimes = actualRuntimes.get(execution.lane) ?? new Set();
			runtimes.add(runtime);
			actualRuntimes.set(execution.lane, runtimes);
		}
	}

	const actualMembers = new Set(actualRuntimes.keys());
	assert(
		JSON.stringify(sorted(actualMembers)) ===
			JSON.stringify(sorted(expectedMembers)),
		`${label} lane membership drifted: expected ${JSON.stringify(sorted(expectedMembers))}, found ${JSON.stringify(sorted(actualMembers))}`,
	);
	for (const laneId of memberIds) {
		const lane = laneById.get(laneId);
		const workflowRuntimes =
			aggregateWorkflowRuntimes?.[laneId] ??
			lane.workflowRuntimes ??
			lane.hostRuntimes ??
			lane.runtimes;
		assertArray(lane.runtimes, `${laneId}.runtimes`);
		assertArray(workflowRuntimes, `${laneId}.workflowRuntimes`);
		const expectedRuntimes = sorted(new Set(workflowRuntimes));
		const foundRuntimes = sorted(actualRuntimes.get(laneId) ?? []);
		assert(
			JSON.stringify(foundRuntimes) === JSON.stringify(expectedRuntimes),
			`${label} runtimes drifted for ${laneId}: expected ${JSON.stringify(expectedRuntimes)}, found ${JSON.stringify(foundRuntimes)}`,
		);
	}
	return { aggregate: selectedAggregate, executions: actual };
}

/**
 * File-backed convenience wrapper for the future control-plane checker.
 * The canonical model must explicitly provide the aggregate memberships used
 * by each workflow; missing aggregates fail closed instead of treating mapped
 * lanes as verified.
 */
export function validateWorkflowProjections(
	lanes,
	{
		rootDir = process.cwd(),
		workflows = {
			"pull-request-ci": ".github/workflows/build-and-test.yml",
			release: ".github/workflows/release.yml",
		},
		aggregates = {},
	} = {},
) {
	assert(lanes?.aggregates, "canonical lane model aggregates are required");
	const results = {};
	for (const [id, workflowConfig] of Object.entries(workflows)) {
		const config =
			typeof workflowConfig === "string"
				? { path: workflowConfig }
				: workflowConfig;
		assert(
			config && typeof config === "object",
			`${id} workflow projection configuration is required`,
		);
		const relativePath = config.path ?? config.file ?? config.workflow;
		assert(
			typeof relativePath === "string" && relativePath.length > 0,
			`${id} workflow projection path is required`,
		);
		const aggregateId = aggregates[id] ?? config.aggregate ?? id;
		const source = readFileSync(resolve(rootDir, relativePath), "utf8");
		results[id] = validateWorkflowAggregate(source, {
			lanes,
			aggregate: lanes.aggregates[aggregateId],
			aggregateId,
			rootDir,
			label: `${id} workflow aggregate`,
			expectedJobs:
				config.expectedJobs ??
				(Array.isArray(config.jobs) ? undefined : config.jobs),
			job: config.job,
			jobIds: Array.isArray(config.jobs) ? config.jobs : undefined,
		});
	}
	return results;
}

