import { join } from "node:path";
import { pathToFileURL } from "node:url";

import { releaseCandidateArtifact } from "../../scripts/release-candidate-artifacts.mjs";

const npmCommand = process.platform === "win32" ? "npm.cmd" : "npm";

function runNpm(args, options = {}) {
	const result = spawnSync(npmCommand, args, {
		encoding: "utf8",
		env: process.env,
		...options,
	});

	if (result.error) {
		throw result.error;
	}

	if (result.status !== 0) {
		if (result.stdout) console.error(result.stdout);
		if (result.stderr) console.error(result.stderr);
		process.exit(result.status ?? 1);
	}

	return result;
}

function waitForMcpResponse(child, id, timeoutMs = 10_000) {
	return new Promise((resolve, reject) => {
		let buffer = "";
		const timer = setTimeout(() => {
			cleanup();
			reject(new Error(`Timed out waiting for MCP response ${id}`));
		}, timeoutMs);
		const cleanup = () => {
			clearTimeout(timer);
			child.stdout.removeListener("data", onData);
			child.removeListener("error", onError);
			child.removeListener("exit", onExit);
		};
		const onData = (chunk) => {
			buffer += chunk.toString();
			for (const line of buffer.split("\n").slice(0, -1)) {
				if (!line.trim()) continue;
				let message;
				try {
					message = JSON.parse(line);
				} catch {
					continue;
				}
				if (message?.id === id) {
					cleanup();
					resolve(message);
					return;
				}
			}
			buffer = buffer.includes("\n")
				? buffer.slice(buffer.lastIndexOf("\n") + 1)
				: buffer;
		};
		const onError = (error) => {
			cleanup();
			reject(error);
		};
		const onExit = (code, signal) => {
			cleanup();
			reject(
				new Error(`MCP process exited before response: ${code ?? signal}`),
			);
		};
		child.stdout.on("data", onData);
		child.once("error", onError);
		child.once("exit", onExit);
	});
}

async function stopChild(child) {
	if (child.exitCode !== null || child.signalCode !== null) return;
	await new Promise((resolve) => {
		let timer = null;
		const finish = () => {
			if (timer !== null) clearTimeout(timer);
			child.off("exit", finish);
			resolve();
		};
		timer = setTimeout(() => {
			child.kill("SIGKILL");
			finish();
		}, 2_000);
		child.once("exit", finish);
		child.kill("SIGTERM");
	});
}

const candidate = await releaseCandidateArtifact("packages/node");
const tarball = candidate.path;
const inventory = spawnSync("tar", ["-tzf", tarball], { encoding: "utf8" });
if (inventory.error) throw inventory.error;
if (inventory.status !== 0) throw new Error("Could not inspect Node tarball");
const files = new Set(
	inventory.stdout
		.split("\n")
		.filter(Boolean)
		.map((path) => path.replace(/^package\//, "")),
);
const manifestResult = spawnSync(
	"tar",
	["-xOf", tarball, "package/package.json"],
	{ encoding: "utf8" },
);
if (manifestResult.error) throw manifestResult.error;
if (manifestResult.status !== 0)
	throw new Error("Could not read the packed Node manifest");
const packedManifest = JSON.parse(manifestResult.stdout);
const requiredFiles = [
	"README.md",
	"dist/cli.mjs",
	"dist/index.d.mts",
	"dist/index.mjs",
	"package.json",
	"server.json",
];

for (const path of requiredFiles) {
	if (!files.has(path)) {
		throw new Error(`Packed package is missing required file: ${path}`);
	}
}

if (packedManifest.bin?.["hevy-mcp"] !== "dist/cli.mjs") {
	throw new Error("package.json must expose hevy-mcp from dist/cli.mjs");
}

for (const section of [
	"dependencies",
	"optionalDependencies",
	"peerDependencies",
]) {
	for (const name of Object.keys(packedManifest[section] ?? {})) {
		if (name.startsWith("@hevy-mcp/")) {
			throw new Error(
				`Public package must not declare private workspace ${name}`,
			);
		}
	}
}

const emittedFiles = [...files].filter((path) =>
	/\.(?:mjs|cjs|js|d\.mts|d\.cts|d\.ts)$/.test(path),
);
for (const path of emittedFiles) {
	const content = spawnSync("tar", ["-xOf", tarball, `package/${path}`], {
		encoding: "utf8",
	});
	if (content.error) throw content.error;
	if (content.status !== 0)
		throw new Error(`Could not read packed artifact file: ${path}`);
	const packedText = content.stdout;
	if (
		packedText.includes("@hevy-mcp/core") ||
		packedText.includes("@hevy-mcp/hevy-client")
	) {
		throw new Error(
			`Packed artifact contains a private workspace import: ${path}`,
		);
	}
}

console.log(
	`Package inventory passed: ${files.size} entries, ${candidate.size} bytes.`,
);

const tempDir = mkdtempSync(join(tmpdir(), "hevy-mcp-pack-"));
try {
	if (
		packedManifest.repository?.url !== "https://github.com/chrisdoc/hevy-mcp"
	) {
		throw new Error("Package repository metadata missing");
	}
	const installDir = join(tempDir, "consumer");
	mkdirSync(installDir, { recursive: true });
	runNpm(
		[
			"install",
			"--prefix",
			installDir,
			tarball,
			"--ignore-scripts",
			"--no-audit",
			"--no-fund",
		],
		{ stdio: "pipe" },
	);
	const binaryName = process.platform === "win32" ? "hevy-mcp.cmd" : "hevy-mcp";
	const binaryPath = join(installDir, "node_modules", ".bin", binaryName);
	for (const [flag, pattern] of [
		["--help", /Usage:\s*\n\s*hevy-mcp/u],
		["--version", /^hevy-mcp v\S+/mu],
	]) {
		const cliCheck = spawnSync(binaryPath, [flag], {
			cwd: installDir,
			encoding: "utf8",
		});
		const output = `${cliCheck.stdout ?? ""}\n${cliCheck.stderr ?? ""}`;
		if (cliCheck.status !== 0 || !pattern.test(output)) {
			throw new Error(`Installed CLI failed ${flag} smoke check`);
		}
	}
	const importCheck = spawnSync(
		process.execPath,
		[
			"-e",
			"import('hevy-mcp').then(({createNodeMcpServer,runStdioServer}) => { if (typeof createNodeMcpServer !== 'function' || typeof runStdioServer !== 'function') process.exit(1); })",
		],
		{ cwd: installDir, encoding: "utf8" },
	);
	if (importCheck.status !== 0) throw new Error("packed API import failed");

	const fetchShimPath = join(tempDir, "pack-smoke-fetch.mjs");
	writeFileSync(
		fetchShimPath,
		"globalThis.fetch = async () => new Response(JSON.stringify({}), { status: 200, headers: { 'content-type': 'application/json' } });\n",
	);
	const nodeOptions = [
		process.env.NODE_OPTIONS,
		`--import=${pathToFileURL(fetchShimPath).href}`,
	]
		.filter(Boolean)
		.join(" ");
	const child = spawn(binaryPath, [], {
		cwd: installDir,
		env: {
			...process.env,
			HEVY_API_KEY: "pack-smoke-key",
			NODE_OPTIONS: nodeOptions,
		},
		stdio: ["pipe", "pipe", "pipe"],
	});
	child.stderr.resume();
	try {
		child.stdin.write(
			`${JSON.stringify({
				jsonrpc: "2.0",
				id: 1,
				method: "initialize",
				params: {
					protocolVersion: "2025-11-25",
					capabilities: {},
					clientInfo: { name: "pack-smoke", version: "1.0.0" },
				},
			})}\n`,
		);
		const initialize = await waitForMcpResponse(child, 1);
		if (typeof initialize.result?.protocolVersion !== "string") {
			throw new Error("Installed CLI MCP initialize handshake failed");
		}
		child.stdin.write(
			`${JSON.stringify({
				jsonrpc: "2.0",
				method: "notifications/initialized",
			})}\n`,
		);
		child.stdin.write(
			`${JSON.stringify({
				jsonrpc: "2.0",
				id: 2,
				method: "tools/list",
				params: {},
			})}\n`,
		);
		const toolsList = await waitForMcpResponse(child, 2);
		if (!Array.isArray(toolsList.result?.tools)) {
			throw new Error("Installed CLI MCP tools/list handshake failed");
		}
	} finally {
		await stopChild(child);
	}
} finally {
	rmSync(tempDir, { recursive: true, force: true });
}

import { mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawn } from "node:child_process";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

import { releaseCandidateArtifact } from "../../../scripts/release-candidate-artifacts.mjs";

const exec = promisify(execFile);
const repositoryRoot = fileURLToPath(new URL("../../..", import.meta.url));
const dir = await mkdtemp(join(tmpdir(), "hevy-cli-pack-"));

function runWithInput(command, args, options, input) {
	return new Promise((resolve, reject) => {
		const child = spawn(command, args, {
			...options,
			stdio: ["pipe", "pipe", "pipe"],
		});
		let stdout = "";
		let stderr = "";
		child.stdout.setEncoding("utf8");
		child.stderr.setEncoding("utf8");
		child.stdout.on("data", (chunk) => (stdout += chunk));
		child.stderr.on("data", (chunk) => (stderr += chunk));
		child.on("error", reject);
		child.on("close", (code) => resolve({ code, stdout, stderr }));
		child.stdin.end(input);
	});
}

try {
	const { path: tarball } = await releaseCandidateArtifact("packages/cli");
	const manifest = JSON.parse(
		(await exec("tar", ["-xOf", tarball, "package/package.json"])).stdout,
	);
	if (manifest.name !== "@chrisdoc/hevy-cli")
		throw new Error("CLI package metadata missing");
	if (manifest.repository?.url !== "https://github.com/chrisdoc/hevy-mcp")
		throw new Error("CLI package repository metadata missing");
	if (manifest.dependencies && Object.keys(manifest.dependencies).length)
		throw new Error("CLI has runtime dependencies");
	if (manifest.scripts?.prepack !== "npm run build")
		throw new Error("CLI package does not build before packing");

	const consumer = join(dir, "consumer");
	await mkdir(consumer);
	await exec(
		"npm",
		[
			"install",
			"--no-audit",
			"--no-fund",
			"--ignore-scripts",
			"--prefix",
			consumer,
			tarball,
		],
		{ cwd: repositoryRoot },
	);
	const binary = join(consumer, "node_modules/.bin/hevy");
	const key = "00000000-0000-0000-0000-000000000000";
	const fakeFetch = join(dir, "fake-fetch.mjs");
	const requestLog = join(dir, "requests.jsonl");
	await writeFile(
		fakeFetch,
		`import { appendFile } from "node:fs/promises";
const log = process.env.HEVY_SMOKE_LOG;
globalThis.fetch = async (input, init = {}) => {
	const headers = Object.fromEntries(new Headers(init.headers).entries());
	const request = {
		method: init.method ?? "GET",
		url: String(input),
		headers,
		body: typeof init.body === "string" ? init.body : "",
	};
	await appendFile(log, JSON.stringify(request) + "\\n");
	const pathname = new URL(request.url).pathname;
	const response =
		request.method === "POST" && pathname === "/v1/routine_folders"
			? { status: 201, body: { id: 3 } }
			: request.method === "PUT" && pathname === "/v1/workouts/workout-1"
				? { status: 200, body: { id: "workout-1" } }
				: { status: 404, body: { error: "unexpected request" } };
	return new Response(JSON.stringify(response.body), {
		status: response.status,
		headers: { "content-type": "application/json" },
	});
};
`,
		"utf8",
	);
	const env = {
		...process.env,
		HEVY_API_KEY: key,
		HEVY_SMOKE_LOG: requestLog,
		NODE_OPTIONS: `--import=${fakeFetch}`,
	};
	const version = await exec(binary, ["--version"], { env });
	if (version.stdout !== `${manifest.version}\n` || version.stderr !== "")
		throw new Error("Packed CLI executable did not report its version");

	const help = await exec(binary, ["--help"], { env });
	if (
		help.stderr !== "" ||
		!help.stdout.includes("workouts list|create|update") ||
		!help.stdout.includes("routines list|create|update") ||
		!help.stdout.includes("exercises create") ||
		!help.stdout.includes("measurements list|get|create|update") ||
		!help.stdout.includes("folders create") ||
		help.stdout.toLowerCase().includes("delete")
	)
		throw new Error("Packed CLI help mutation matrix is incorrect");

	const folder = await exec(
		binary,
		[
			"folders",
			"create",
			"--data",
			'{"routine_folder":{"title":"Strength"}}',
			"--yes",
			"--json",
		],
		{ env },
	);
	if (folder.stderr !== "") throw new Error("Packed folder create failed");
	if (JSON.parse(folder.stdout).routine_folder.id !== 3)
		throw new Error("Packed folder response was not normalized");

	const workout = {
		workout_id: "workout-1",
		workout: {
			title: "Push",
			start_time: "2024-01-01T10:00:00Z",
			end_time: "2024-01-01T11:00:00Z",
			exercises: [
				{
					exercise_template_id: "exercise-1",
					sets: [{ type: "normal", weight_kg: 50, reps: 5 }],
				},
			],
		},
	};
	const update = await runWithInput(
		binary,
		["workouts", "update", "workout-1", "--data", "@-", "--yes", "--json"],
		{ env },
		JSON.stringify(workout),
	);
	if (update.code !== 0 || update.stderr !== "")
		throw new Error("Packed workout update failed");
	if (JSON.parse(update.stdout).workout_id !== "workout-1")
		throw new Error("Packed workout response was not normalized");

	const requests = (await readFile(requestLog, "utf8"))
		.trim()
		.split("\n")
		.map((line) => JSON.parse(line));
	if (requests.length !== 2) throw new Error("Unexpected packed request count");
	const [folderRequest, workoutRequest] = requests;
	if (
		folderRequest.method !== "POST" ||
		new URL(folderRequest.url).pathname !== "/v1/routine_folders" ||
		folderRequest.headers["api-key"] !== key ||
		JSON.stringify(JSON.parse(folderRequest.body)) !==
			JSON.stringify({ routine_folder: { title: "Strength" } })
	)
		throw new Error("Packed folder request contract is incorrect");
	if (
		workoutRequest.method !== "PUT" ||
		new URL(workoutRequest.url).pathname !== "/v1/workouts/workout-1" ||
		workoutRequest.headers["api-key"] !== key ||
		JSON.stringify(JSON.parse(workoutRequest.body)) !==
			JSON.stringify({
				workout: {
					title: "Push",
					start_time: "2024-01-01T10:00:00Z",
					end_time: "2024-01-01T11:00:00Z",
					is_private: false,
					exercises: [
						{
							exercise_template_id: "exercise-1",
							sets: [
								{
									type: "normal",
									weight_kg: 50,
									reps: 5,
								},
							],
						},
					],
				},
			})
	)
		throw new Error("Packed workout request contract is incorrect");
} finally {
	await rm(dir, { recursive: true, force: true });
}

