arguments.workflowScript:
const results = await runs.all([
  { key: "script-inventory", agent: "reviewer", task: "Review /root/hevy-mcp scripts for usefulness, not code style. This is a read-only audit: do not modify any project/source files. Inspect every file under scripts/, package.json, project.json, nx.json, repository/*.json, and CI/docs references. Classify each executable/module and each declaration helper as KEEP (high-value product/build/release safety), CONDITIONAL (valuable but could be simplified), or REMOVE (nice-to-have/convenience/duplicative). For every recommendation cite concrete file/line references, call sites, CI/release impact, and deletion dependency closure. Pay special attention to whether the control-plane machinery is justified versus over-engineered. Return a concise but thorough evidence-backed report, with no implementation changes.", output: false },
  { key: "script-tests", agent: "reviewer", task: "Audit only tests under /root/hevy-mcp/scripts/ (and the adjacent tests/unit coverage of scripts) for usefulness and risk. Read the corresponding production scripts and their CI/release callers. Do not modify files. Classify each test file and major test group as KEEP, TRIM/CONSOLIDATE, or REMOVE, based on whether it catches high-impact regressions versus testing formatting, platform trivia, implementation details, or brittle configuration snapshots. Identify important untested high-impact script behavior too. Cite file and line ranges and give a deletion-safe dependency plan.", output: false },
  { key: "simplification", agent: "reviewer", task: "Perform an adversarial maintainability/product-value audit of /root/hevy-mcp/scripts and the surrounding control-plane configuration. Read current code, recent git history, package/Nx targets, workflows, and docs. The user wants only scripts with high usefulness, not nice-to-haves. Do not edit. Challenge every auxiliary layer (canonical models, workflow projection parser, generated checks, token-cost reporting, hook installer, docs renderer, wrappers). Return a prioritized keep/remove/replace recommendation, explain operational consequences, and distinguish true safety/release gates from developer convenience or documentation hygiene. Cite evidence and avoid generic advice.", output: false }
]);
return results.map(({ key, output }) => ({ key, output }));

