   685	export function validateAggregateAcyclicity(aggregates) {
   686		const visiting = new Set();
   687		const visited = new Set();
   688		const visit = (id, stack) => {
   689			if (visiting.has(id))
   690				throw new Error(
   691					"Validation aggregate cycle: " + [...stack, id].join(" -> "),
   692				);
   693			if (visited.has(id)) return;
   694			const aggregate = aggregates[id];
   695			if (!aggregate) return;
   696			visiting.add(id);
   697			for (const member of aggregate.lanes || [])
   698				if (aggregates[member]) visit(member, [...stack, id]);
   699			visiting.delete(id);
   700			visited.add(id);
   701		};
   702		for (const id of Object.keys(aggregates || {})) visit(id, []);
   703	}
