   705	export function flattenAggregateLanes(aggregates, laneIds, aggregateId) {
   706		const flatten = (id, stack = []) => {
   707			assert(
   708				!stack.includes(id),
   709				"validation aggregate cycle: " + [...stack, id].join(" -> "),
   710			);
   711			const aggregate = aggregates[id];
   712			assert(aggregate, "validation aggregate " + id + " is required");
   713			return aggregate.lanes.flatMap((member) =>
   714				laneIds.has(member) ? [member] : flatten(member, [...stack, id]),
   715			);
   716		};
   717		return flatten(aggregateId);
   718	}
